```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseERP.Infrastructure.Data;

public readonly record struct PoLineRecord(
    Guid LineId,
    int LineNumber,
    string ItemSku,
    decimal Quantity,
    decimal UnitCost,
    decimal LineTotal
);

public sealed record PurchaseOrderDetail(
    Guid OrderId,
    Guid TenantId,
    string OrderNumber,
    Guid VendorId,
    string Status,
    decimal TotalAmount,
    DateTimeOffset OrderDateUtc,
    IReadOnlyList<PoLineRecord> LineItems
);

public sealed class PurchaseOrderQueryService
{
    private readonly string _connectionString;

    public PurchaseOrderQueryService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<PurchaseOrderDetail?> GetPurchaseOrderDetailAsync(
        Guid tenantId,
        Guid orderId,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Erp_GetPurchaseOrderFullDetail", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        // Explicit parameter mapping prevents implicit conversion penalties and allows plan caching
        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@OrderId", SqlDbType.UniqueIdentifier) { Value = orderId });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        // --- RESULT SET 1: Order Header ---
        if (!await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            return null; // Header not found
        }

        int ordOrderId = reader.GetOrdinal("OrderId");
        int ordTenantId = reader.GetOrdinal("TenantId");
        int ordOrderNum = reader.GetOrdinal("OrderNumber");
        int ordVendorId = reader.GetOrdinal("VendorId");
        int ordStatus = reader.GetOrdinal("Status");
        int ordTotal = reader.GetOrdinal("TotalAmount");
        int ordDate = reader.GetOrdinal("OrderDateUtc");

        var retrievedOrderId = reader.GetGuid(ordOrderId);
        var retrievedTenantId = reader.GetGuid(ordTenantId);
        var orderNumber = reader.GetString(ordOrderNum);
        var vendorId = reader.GetGuid(ordVendorId);
        var status = reader.GetString(ordStatus);
        var totalAmount = reader.GetDecimal(ordTotal);
        var orderDateUtc = reader.GetDateTimeOffset(ordDate);

        // --- RESULT SET 2: Order Line Items ---
        var lineItems = new List<PoLineRecord>();

        if (await reader.NextResultAsync(cancellationToken).ConfigureAwait(false))
        {
            int ordLineId = reader.GetOrdinal("LineId");
            int ordLineNum = reader.GetOrdinal("LineNumber");
            int ordSku = reader.GetOrdinal("ItemSku");
            int ordQty = reader.GetOrdinal("Quantity");
            int ordUnitCost = reader.GetOrdinal("UnitCost");
            int ordLineTotal = reader.GetOrdinal("LineTotal");

            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                lineItems.Add(new PoLineRecord(
                    LineId: reader.GetGuid(ordLineId),
                    LineNumber: reader.GetInt32(ordLineNum),
                    ItemSku: reader.GetString(ordSku),
                    Quantity: reader.GetDecimal(ordQty),
                    UnitCost: reader.GetDecimal(ordUnitCost),
                    LineTotal: reader.GetDecimal(ordLineTotal)
                ));
            }
        }

        return new PurchaseOrderDetail(
            OrderId: retrievedOrderId,
            TenantId: retrievedTenantId,
            OrderNumber: orderNumber,
            VendorId: vendorId,
            Status: status,
            TotalAmount: totalAmount,
            OrderDateUtc: orderDateUtc,
            LineItems: lineItems
        );
    }
}
```

