    PatientId       UNIQUEIDENTIFIER NOT NULL,
    LoincCode       VARCHAR(20)      NOT NULL,
    ObservationName NVARCHAR(200)    NOT NULL,
    NumericValue    DECIMAL(18, 4)   NULL,
    UnitOfMeasure   NVARCHAR(30)     NULL,
    Interpretation  NVARCHAR(50)     NULL,
    RecordedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_ClinicalObs_Date DEFAULT SYSUTCDATETIME(),
    RecordedByUserId UNIQUEIDENTIFIER NOT NULL,
    CONSTRAINT PK_ClinicalObservations PRIMARY KEY CLUSTERED (ObservationId),
    CONSTRAINT FK_ClinicalObservations_Patient FOREIGN KEY (PatientId) REFERENCES dbo.Patients (PatientId)
);
GO

-- Row-Level Security (RLS) Predicate Function for Tenant Isolation
CREATE OR ALTER FUNCTION Security.fn_TenantSecurityPredicate(@TenantId UNIQUEIDENTIFIER)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN 
    SELECT 1 AS AccessGranted
    WHERE @TenantId = CAST(SESSION_CONTEXT(N'TenantId') AS UNIQUEIDENTIFIER)
       OR CAST(SESSION_CONTEXT(N'IsSystemSuperAdmin') AS BIT) = 1;
GO

-- Apply RLS Security Policy
CREATE SECURITY POLICY Security.TenantIsolationPolicy
ADD FILTER PREDICATE Security.fn_TenantSecurityPredicate(TenantId) ON dbo.Patients,
ADD BLOCK PREDICATE Security.fn_TenantSecurityPredicate(TenantId) ON dbo.Patients AFTER INSERT,
ADD FILTER PREDICATE Security.fn_TenantSecurityPredicate(TenantId) ON dbo.ClinicalObservations,
ADD BLOCK PREDICATE Security.fn_TenantSecurityPredicate(TenantId) ON dbo.ClinicalObservations AFTER INSERT
WITH (STATE = ON, SCHEMABINDING = ON);
GO

CREATE TYPE dbo.tvp_ClinicalObservationItem AS TABLE
(
    LoincCode       VARCHAR(20)    NOT NULL,
    ObservationName NVARCHAR(200)  NOT NULL,
    NumericValue    DECIMAL(18, 4) NULL,
    UnitOfMeasure   NVARCHAR(30)   NULL,
    Interpretation  NVARCHAR(50)   NULL
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Clinical_RecordObservations
    @PatientId        UNIQUEIDENTIFIER,
    @RecordedByUserId UNIQUEIDENTIFIER,
    @Observations     dbo.tvp_ClinicalObservationItem READONLY,
    @InsertedCount    INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @CurrentTenantId UNIQUEIDENTIFIER = CAST(SESSION_CONTEXT(N'TenantId') AS UNIQUEIDENTIFIER);

    IF @CurrentTenantId IS NULL
    BEGIN
        THROW 55001, 'Invalid session context: TenantId must be initialized.', 1;
        RETURN -1;
    END

    IF NOT EXISTS (SELECT 1 FROM dbo.Patients WHERE PatientId = @PatientId)
    BEGIN
        THROW 55002, 'Patient not found or unauthorized under current tenant context.', 1;
        RETURN -1;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.ClinicalObservations 
            (TenantId, PatientId, LoincCode, ObservationName, NumericValue, UnitOfMeasure, Interpretation, RecordedByUserId)
        SELECT 
            @CurrentTenantId,
            @PatientId,
            LoincCode,
            ObservationName,
            NumericValue,
            UnitOfMeasure,
            Interpretation,
            @RecordedByUserId
        FROM @Observations;

        SET @InsertedCount = @@ROWCOUNT;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

