{
    private readonly string _connectionString;

    public ClinicalRecordRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<int> RecordPatientObservationsAsync(
        Guid tenantId,
        Guid patientId,
        Guid recordedByUserId,
        IReadOnlyList<ObservationItemDto> observations,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(observations);
        if (observations.Count == 0)
        {
            throw new ArgumentException("Observations collection cannot be empty.", nameof(observations));
        }

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Initialize Session Context for Row-Level Security
        await SetTenantContextAsync(connection, tenantId, cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Clinical_RecordObservations", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@PatientId", SqlDbType.UniqueIdentifier) { Value = patientId });
        command.Parameters.Add(new SqlParameter("@RecordedByUserId", SqlDbType.UniqueIdentifier) { Value = recordedByUserId });

        var tvpParam = new SqlParameter("@Observations", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_ClinicalObservationItem",
            Value = BuildObservationsDataTable(observations)
        };
        command.Parameters.Add(tvpParam);

        var countParam = new SqlParameter("@InsertedCount", SqlDbType.Int)
        {
            Direction = ParameterDirection.Output
        };
        command.Parameters.Add(countParam);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        return countParam.Value is int count ? count : 0;
    }

    public async IAsyncEnumerable<ClinicalObservationRecordDto> StreamPatientObservationsAsync(
        Guid tenantId,
        Guid patientId,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        const string sql = @"
            SELECT 
                ObservationId, PatientId, LoincCode, ObservationName, NumericValue, UnitOfMeasure, RecordedAtUtc
            FROM dbo.ClinicalObservations
            WHERE PatientId = @PatientId
            ORDER BY RecordedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await SetTenantContextAsync(connection, tenantId, cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandTimeout = 30
        };
        command.Parameters.Add(new SqlParameter("@PatientId", SqlDbType.UniqueIdentifier) { Value = patientId });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordId = reader.GetOrdinal("ObservationId");
        int ordPatient = reader.GetOrdinal("PatientId");
        int ordLoinc = reader.GetOrdinal("LoincCode");
        int ordName = reader.GetOrdinal("ObservationName");
        int ordVal = reader.GetOrdinal("NumericValue");
        int ordUnit = reader.GetOrdinal("UnitOfMeasure");
        int ordDate = reader.GetOrdinal("RecordedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new ClinicalObservationRecordDto(
                ObservationId: reader.GetGuid(ordId),
                PatientId: reader.GetGuid(ordPatient),
                LoincCode: reader.GetString(ordLoinc),
                ObservationName: reader.GetString(ordName),
                NumericValue: reader.IsDBNull(ordVal) ? null : reader.GetDecimal(ordVal),
                UnitOfMeasure: reader.IsDBNull(ordUnit) ? null : reader.GetString(ordUnit),
                RecordedAtUtc: reader.GetDateTime(ordDate)
            );
        }
    }

    private static async Task SetTenantContextAsync(SqlConnection conn, Guid tenantId, CancellationToken ct)
    {
        await using var contextCmd = new SqlCommand("EXEC sp_set_session_context @key=N'TenantId', @value=@TenantId;", conn);
        contextCmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        await contextCmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
    }

    private static DataTable BuildObservationsDataTable(IReadOnlyList<ObservationItemDto> items)
    {
        var dt = new DataTable();
        dt.Columns.Add("LoincCode", typeof(string));
        dt.Columns.Add("ObservationName", typeof(string));
        dt.Columns.Add("NumericValue", typeof(decimal));
        dt.Columns.Add("UnitOfMeasure", typeof(string));
        dt.Columns.Add("Interpretation", typeof(string));

        foreach (var item in items)
        {
            dt.Rows.Add(
                item.LoincCode,
                item.ObservationName,
                (object?)item.NumericValue ?? DBNull.Value,
                (object?)item.UnitOfMeasure ?? DBNull.Value,
                (object?)item.Interpretation ?? DBNull.Value
            );
        }

        return dt;
    }
}
