    {
        var group = routes.MapGroup("/api/v1/clinical")
            .WithTags("Clinical Observation Records")
            .RequireAuthorization();

        group.MapPost("/patients/{patientId:guid}/observations", async Task<Results<Ok<RecordObservationsResponse>, BadRequest<ProblemDetails>, NotFound<ProblemDetails>>> (
            Guid patientId,
            RecordObservationsRequest request,
            ClinicalRecordRepository repository,
            ClaimsPrincipal user,
            CancellationToken cancellationToken) =>
        {
            var userIdClaim = user.FindFirstValue(ClaimTypes.NameIdentifier);
            if (!Guid.TryParse(userIdClaim, out var userId))
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Unauthorized Healthcare Practitioner",
                    Detail = "Valid practitioner claim identifier is required."
                });
            }

            try
            {
                int count = await repository.RecordPatientObservationsAsync(
                    tenantId: request.TenantId,
                    patientId: patientId,
                    recordedByUserId: userId,
                    observations: request.Observations,
                    cancellationToken: cancellationToken
                );

                return TypedResults.Ok(new RecordObservationsResponse(patientId, count, DateTimeOffset.UtcNow));
            }
            catch (SqlException ex) when (ex.Number == 55002)
            {
                return TypedResults.NotFound(new ProblemDetails
                {
                    Title = "Patient Record Not Found",
                    Detail = ex.Message
                });
            }
        })
        .WithName("RecordPatientObservations")
        .Produces<RecordObservationsResponse>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest)
        .ProducesProblem(StatusCodes.Status404NotFound);

