CREATE OR ALTER PROCEDURE dbo.usp_Fuel_PumpInventoryFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @FuelGrade    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        DeliveryId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(GallonsRemaining), 0.00)
        FROM dbo.FuelDeliveries WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND FuelGrade = @FuelGrade
          AND GallonsRemaining > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                DeliveryId,
                GallonsRemaining,
                SUM(GallonsRemaining) OVER (
                    ORDER BY DeliveryTimestamp ASC, DeliveryId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.FuelDeliveries WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND FuelGrade = @FuelGrade
              AND GallonsRemaining > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                DeliveryId,
                GallonsRemaining,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN GallonsRemaining
                    ELSE GallonsRemaining - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - GallonsRemaining < @RequiredQty
        )
        INSERT INTO @AllocatedLots (DeliveryId, AllocatedUnits)
        SELECT DeliveryId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.GallonsRemaining = target.GallonsRemaining - alloc.AllocatedUnits
        FROM dbo.FuelDeliveries target
        INNER JOIN @AllocatedLots alloc ON target.DeliveryId = alloc.DeliveryId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

