Here is the complete, production-grade C# .NET 10 implementation:

```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;

namespace EnterprisePlatform.Infrastructure.Resilience;

public sealed class SqlResilientExecutor
{
    private readonly string _connectionString;
    private readonly ILogger<SqlResilientExecutor> _logger;
    private readonly int _maxRetries;
    private static readonly Random _jitter = new();

    public SqlResilientExecutor(string connectionString, ILogger<SqlResilientExecutor> logger, int maxRetries = 4)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _maxRetries = maxRetries;
    }

    public async Task<T> ExecuteWithRetryAsync<T>(
        Func<SqlConnection, SqlTransaction?, CancellationToken, Task<T>> operation,
        IsolationLevel? isolationLevel = null,
        CancellationToken cancellationToken = default)
    {
        int attempt = 0;
        while (true)
        {
            attempt++;
            try
            {
                await using var connection = new SqlConnection(_connectionString);
                await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

                if (isolationLevel.HasValue)
                {
                    await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(
                        isolationLevel.Value, 
                        cancellationToken
                    ).ConfigureAwait(false);

                    try
                    {
                        var result = await operation(connection, transaction, cancellationToken).ConfigureAwait(false);
                        await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
                        return result;
                    }
                    catch
                    {
                        await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
                        throw;
                    }
                }
                else
                {
                    return await operation(connection, null, cancellationToken).ConfigureAwait(false);
                }
            }
            catch (SqlException ex) when (IsTransient(ex) && attempt <= _maxRetries)
            {
                // Exponential backoff with full jitter: 2^attempt * 100ms + random jitter
                var baseDelayMs = Math.Pow(2, attempt) * 100;
                var jitterMs = _jitter.Next(20, 100);
                var totalDelay = TimeSpan.FromMilliseconds(baseDelayMs + jitterMs);

                _logger.LogWarning(ex, 
                    "Transient SQL exception (Number: {SqlErrorNumber}) on attempt {Attempt}/{MaxRetries}. Retrying in {DelayMs}ms...",
                    ex.Number, attempt, _maxRetries, totalDelay.TotalMilliseconds);

                await Task.Delay(totalDelay, cancellationToken).ConfigureAwait(false);
            }
        }
    }

    private static bool IsTransient(SqlException ex)
    {
        // 1205: Deadlock victim
        // -2: Execution timeout
        // 40613: Azure SQL database unavailable / resuming
        // 40143: Service connection loss
        // 10053, 10054, 10060: Network transport errors
        return ex.Number switch
        {
            1205 or -2 or 40613 or 40143 or 10053 or 10054 or 10060 => true,
            _ => false
        };
    }
}
```

