Here is the complete C# .NET 10 `DbDataReader` subclass:

```csharp
using System;
using System.Collections.Generic;
using System.Data.Common;

namespace Enterprise.IoT.Infrastructure;

public readonly record struct TelemetryEvent(
    Guid DeviceId,
    string MetricName,
    double MetricValue,
    DateTimeOffset TimestampUtc
);

/// <summary>
/// Custom DbDataReader subclass wrapping IEnumerable<TelemetryEvent>.
/// Pass directly to SqlBulkCopy.WriteToServerAsync(reader, ct).
/// SqlBulkCopy calls Read() and GetValue(ordinal) in a tight loop — no DataTable needed.
/// </summary>
public sealed class TelemetryEventReader : DbDataReader
{
    private readonly IEnumerator<TelemetryEvent> _enumerator;
    private TelemetryEvent _current;
    private bool _isClosed;

    public TelemetryEventReader(IEnumerable<TelemetryEvent> source)
        => _enumerator = source.GetEnumerator();

    // SqlBulkCopy calls Read() for every row — advance the enumerator and cache current
    public override bool Read()
    {
        bool moved = _enumerator.MoveNext();
        if (moved) _current = _enumerator.Current;
        return moved;
    }

    // Must match the number of ColumnMappings declared on SqlBulkCopy
    public override int FieldCount => 4;

    // SqlBulkCopy reads each column value via GetValue(ordinal) per row
    public override object GetValue(int ordinal) => ordinal switch
    {
        0 => _current.DeviceId,
        1 => _current.MetricName,
        2 => _current.MetricValue,
        3 => _current.TimestampUtc,
        _ => throw new IndexOutOfRangeException($"Ordinal {ordinal} out of range. FieldCount = 4.")
    };

    public override string GetName(int ordinal) => ordinal switch
    {
        0 => "DeviceId",
        1 => "MetricName",
        2 => "MetricValue",
        3 => "TimestampUtc",
        _ => throw new IndexOutOfRangeException()
    };

    public override int GetOrdinal(string name) => name switch
    {
        "DeviceId"    => 0,
        "MetricName"  => 1,
        "MetricValue" => 2,
        "TimestampUtc"=> 3,
        _ => throw new IndexOutOfRangeException($"Column '{name}' not found.")
    };

    public override Type GetFieldType(int ordinal) => ordinal switch
    {
        0 => typeof(Guid),
        1 => typeof(string),
        2 => typeof(double),
        3 => typeof(DateTimeOffset),
        _ => throw new IndexOutOfRangeException()
    };

    public override void Close()
    {
        _isClosed = true;
        _enumerator.Dispose();
    }

    // Required abstract members — minimal implementations for SqlBulkCopy use
    public override bool IsDBNull(int ordinal)   => false;
    public override bool HasRows                 => true;
    public override bool IsClosed                => _isClosed;
    public override int  RecordsAffected         => -1;
    public override int  Depth                   => 0;
    public override bool NextResult()            => false;
    public override Guid   GetGuid(int o)   => (Guid)GetValue(o);
    public override string GetString(int o) => (string)GetValue(o);
    public override double GetDouble(int o) => (double)GetValue(o);
    public override bool   GetBoolean(int o)=> (bool)GetValue(o);
    public override byte   GetByte(int o)   => (byte)GetValue(o);
    public override char   GetChar(int o)   => (char)GetValue(o);
    public override short  GetInt16(int o)  => (short)GetValue(o);
    public override int    GetInt32(int o)  => (int)GetValue(o);
    public override long   GetInt64(int o)  => (long)GetValue(o);
    public override float  GetFloat(int o)  => (float)GetValue(o);
    public override decimal GetDecimal(int o) => (decimal)GetValue(o);
    public override DateTime GetDateTime(int o) => ((DateTimeOffset)GetValue(o)).UtcDateTime;
    public override long GetBytes(int o, long d, byte[]? b, int bo, int l) => 0;
    public override long GetChars(int o, long d, char[]? b, int bo, int l) => 0;
    public override int  GetValues(object[] v) => 0;
    public override string GetDataTypeName(int o) => GetFieldType(o).Name;
    public override System.Collections.IEnumerator GetEnumerator() => throw new NotSupportedException();
}
```

### Key Architectural Highlights:
- **`class TelemetryEventReader : DbDataReader`** — inherits from `DbDataReader` in `System.Data.Common`. This is the correct base class for custom readers passed to `SqlBulkCopy.WriteToServerAsync`.
- **`override bool Read()`** — advances the internal enumerator and caches `_enumerator.Current` into `_current`. SqlBulkCopy calls this in a tight loop for every row.
- **`override object GetValue(int ordinal)`** — returns the column value for the current row by ordinal position. SqlBulkCopy calls this for each column after `Read()` returns `true`.
- **`override int FieldCount`** — must equal the number of `ColumnMappings` added to `SqlBulkCopy`. Here 4 fields map to DeviceId, MetricName, MetricValue, TimestampUtc.

Here is the high-performance C# .NET 10 ADO.NET streaming implementation for BMS entity `TimesheetBatch`:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.BMS.Infrastructure.Data;

public readonly record struct TimesheetBatchSummary(
    Guid TimesheetId,
    Guid TenantId,
    string ApprovalStatus,
    decimal TotalBillableHours,
    DateTimeOffset CreatedAtUtc
);

public sealed class TimesheetBatchQueryRepository
{
    private readonly string _connectionString;

    public TimesheetBatchQueryRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<TimesheetBatchSummary> StreamByStatusAsync(
        Guid tenantId,
        string status,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                TimesheetId,
                TenantId,
                ApprovalStatus,
                TotalBillableHours,
                CreatedAtUtc
            FROM dbo.BmsTimesheets WITH (READPAST)
            WHERE TenantId = @TenantId
              AND ApprovalStatus = @Status
            ORDER BY CreatedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Status", SqlDbType.NVarChar, 50) { Value = status });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordPk = reader.GetOrdinal("TimesheetId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("ApprovalStatus");
        int ordVal = reader.GetOrdinal("TotalBillableHours");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new TimesheetBatchSummary(
                TimesheetId: reader.GetGuid(ordPk),
                TenantId: reader.GetGuid(ordTenant),
                ApprovalStatus: reader.GetString(ordStatus),
                TotalBillableHours: reader.GetDecimal(ordVal),
                CreatedAtUtc: reader.GetDateTime(ordCreated)
            );
        }
    }
}
```

### Key Architectural Highlights:
- SequentialAccess: Employs sequential streaming to eliminate client memory buffering.
- Ordinal Caching: Caches column ordinals outside the read loop for maximum throughput.
- Cancellation Propagation: Forwards the CancellationToken directly to all async ADO.NET calls.

