Here is the ASP.NET .NET 10 Minimal API implementation with IEndpointFilter pipeline for Retail entity `ShoppingCartReservation`:

```csharp
using System;
using System.Security.Claims;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Routing;

namespace Enterprise.Retail.Api.Endpoints;

public sealed record ShoppingCartReservationDto(Guid ReservationId, Guid TenantId, string ReservationStatus, decimal ReservedCartTotal);

public static class ShoppingCartReservationEndpointExtensions
{
    public static RouteGroupBuilder MapShoppingCartReservationEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/retail/shoppingcartreservations")
            .WithTags("Retail - ShoppingCartReservation")
            .RequireAuthorization();

        group.MapGet("/{id:guid}", async Task<Results<Ok<ShoppingCartReservationDto>, NotFound<ProblemDetails>, UnauthorizedHttpResult>> (
            Guid id,
            ClaimsPrincipal user,
            CancellationToken ct) =>
        {
            var tenantClaim = user.FindFirstValue("TenantId");
            if (!Guid.TryParse(tenantClaim, out var tenantId))
            {
                return TypedResults.Unauthorized();
            }

            var item = new ShoppingCartReservationDto(id, tenantId, "Cancelled", 1500.00m);
            return TypedResults.Ok(item);
        })
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("GetShoppingCartReservationById")
        .Produces<ShoppingCartReservationDto>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound);

        return group;
    }
}

public sealed class TenantContextFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var httpContext = context.HttpContext;
        if (!httpContext.Request.Headers.TryGetValue("X-Tenant-ID", out var raw) || !Guid.TryParse(raw, out var tenantId))
        {
            return Results.Problem("A valid X-Tenant-ID header is required.", statusCode: StatusCodes.Status400BadRequest);
        }
        httpContext.Items["TenantId"] = tenantId;
        return await next(context);
    }
}
```

### Key Architectural Highlights:
- Typed Results: Uses union Results<Ok<T>, NotFound<T>> for explicit OpenAPI documentation.
- Endpoint Filter: Enforces cross-cutting security using IEndpointFilter via AddEndpointFilter<TenantContextFilter>().
- Tenant Claim Validation: Extracts and validates TenantId Guid claims from ClaimsPrincipal.
- Cancellation Binding: Binds CancellationToken from ASP.NET request pipeline.

