                const items = await res.json();
                render(items);
            } catch (err) {
                tbody.innerHTML = `<tr><td colspan="4" class="text-center text-danger py-4">${err.message}</td></tr>`;
            }
        }

        function render(items) {
            if (!items || items.length === 0) {
                tbody.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-4">No records found.</td></tr>';
                return;
            }
            const formatter = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
            tbody.innerHTML = items.map(x => `
                <tr>
                    <td class="fw-semibold">#${x.invoiceid?.substring(0,8) || 'N/A'}</td>
                    <td><span class="badge bg-secondary">${x.paymentstatus}</span></td>
                    <td class="fw-bold">${formatter.format(x.balancedue || 0)}</td>
                    <td class="text-end">
                        <button class="btn btn-sm btn-outline-secondary" onclick="viewDetails('${x.invoiceid}')">View</button>
                    </td>
                </tr>
            `).join('');
        }

        document.getElementById('btnRefresh').addEventListener('click', loadRecords);
        loadRecords();
    </script>
</body>
</html>
```

