        </div>
    </div>

    <script>
        const tbody = document.getElementById('tableBody');
        const token = localStorage.getItem('auth_token') || 'demo_token';
        const tenantId = localStorage.getItem('tenant_id') || '00000000-0000-0000-0000-000000000001';

        async function loadRecords() {
            try {
                const res = await fetch('/api/v1/erp/customerinvoices', {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'X-Tenant-Id': tenantId,
                        'Accept': 'application/json'
                    }
                });
                if (!res.ok) throw new Error('Network error');
                const items = await res.json();
                render(items);
            } catch (err) {
                tbody.innerHTML = `<tr><td colspan="4" class="text-center text-danger py-4">${err.message}</td></tr>`;
            }
        }

        function render(items) {
            if (!items || items.length === 0) {
                tbody.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-4">No records found.</td></tr>';
                return;
            }
