Here is the complete production-grade C# .NET 10 implementation:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.IoT.Infrastructure;

public readonly record struct TelemetryEvent(
    Guid DeviceId,
    string MetricName,
    double MetricValue,
    DateTimeOffset TimestampUtc
);

public sealed class TelemetryIngestionService
{
    private readonly string _connectionString;

    public TelemetryIngestionService(string connectionString)
        => _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));

    public async Task IngestAsync(
        IAsyncEnumerable<TelemetryEvent> events,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        using var bulkCopy = new SqlBulkCopy(connection)
        {
            DestinationTableName = "dbo.DeviceTelemetry",
            BatchSize            = 10_000,
            BulkCopyTimeout      = 120,
            EnableStreaming       = true
        };

        bulkCopy.ColumnMappings.Add("DeviceId",    "DeviceId");
        bulkCopy.ColumnMappings.Add("MetricName",  "MetricName");
        bulkCopy.ColumnMappings.Add("MetricValue", "MetricValue");
        bulkCopy.ColumnMappings.Add("TimestampUtc","TimestampUtc");

        // Pass the custom DbDataReader subclass directly to WriteToServerAsync
        using var reader = new TelemetryStreamReader(events, cancellationToken);
        await bulkCopy.WriteToServerAsync(reader, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>
    /// Private DbDataReader subclass wrapping IAsyncEnumerable<TelemetryEvent>.
    /// SqlBulkCopy calls Read() synchronously; bridge async via GetAwaiter().GetResult().
    /// </summary>
    private sealed class TelemetryStreamReader : DbDataReader
    {
        private readonly IAsyncEnumerator<TelemetryEvent> _enumerator;
        private TelemetryEvent _current;
        private bool _isClosed;

        internal TelemetryStreamReader(IAsyncEnumerable<TelemetryEvent> source, CancellationToken ct)
            => _enumerator = source.GetAsyncEnumerator(ct);

        public override bool Read()
        {
            var moved = _enumerator.MoveNextAsync().AsTask().GetAwaiter().GetResult();
            if (moved) _current = _enumerator.Current;
            return moved;
        }

        public override int FieldCount => 4;

        public override object GetValue(int ordinal) => ordinal switch
        {
            0 => _current.DeviceId,
            1 => _current.MetricName,
            2 => _current.MetricValue,
            3 => _current.TimestampUtc,
            _ => throw new IndexOutOfRangeException($"Ordinal {ordinal} out of range.")
        };

        public override string GetName(int ordinal) => ordinal switch
        {
            0 => "DeviceId",
            1 => "MetricName",
            2 => "MetricValue",
            3 => "TimestampUtc",
            _ => throw new IndexOutOfRangeException()
        };

        public override int  GetOrdinal(string name) => name switch
        {
            "DeviceId"     => 0,
            "MetricName"   => 1,
            "MetricValue"  => 2,
            "TimestampUtc" => 3,
            _              => throw new IndexOutOfRangeException($"Column '{name}' not found.")
        };

        public override Type GetFieldType(int ordinal) => ordinal switch
        {
            0 => typeof(Guid),
            1 => typeof(string),
            2 => typeof(double),
            3 => typeof(DateTimeOffset),
            _ => throw new IndexOutOfRangeException()
        };

        public override bool IsDBNull(int ordinal) => false;
        public override bool HasRows               => true;
        public override bool IsClosed              => _isClosed;
        public override int  RecordsAffected       => -1;
        public override int  Depth                 => 0;
        public override bool NextResult()          => false;

        public override void Close()
        {
            _isClosed = true;
            _enumerator.DisposeAsync().AsTask().GetAwaiter().GetResult();
        }

        public override Guid    GetGuid(int o)    => (Guid)GetValue(o);
        public override string  GetString(int o)  => (string)GetValue(o);
        public override double  GetDouble(int o)  => (double)GetValue(o);
        public override long    GetBytes(int o, long d, byte[]? b, int bo, int l) => 0;
        public override long    GetChars(int o, long d, char[]? b, int bo, int l) => 0;
        public override int     GetValues(object[] v) => 0;
        public override bool    GetBoolean(int o) => (bool)GetValue(o);
        public override byte    GetByte(int o)    => (byte)GetValue(o);
        public override char    GetChar(int o)    => (char)GetValue(o);
        public override short   GetInt16(int o)   => (short)GetValue(o);
        public override int     GetInt32(int o)   => (int)GetValue(o);
        public override long    GetInt64(int o)   => (long)GetValue(o);
        public override float   GetFloat(int o)   => (float)GetValue(o);
        public override decimal GetDecimal(int o) => (decimal)GetValue(o);
        public override DateTime GetDateTime(int o) => ((DateTimeOffset)GetValue(o)).UtcDateTime;
        public override string GetDataTypeName(int o) => GetFieldType(o).Name;
        public override System.Collections.IEnumerator GetEnumerator() => throw new NotSupportedException();
    }
}
```

### Key Architectural Highlights:
- **`DbDataReader` subclass `override bool Read()`**: Inheriting from `DbDataReader` and overriding `Read()` plus `GetValue(int ordinal)` is the correct pattern. SqlBulkCopy's internal row pump calls these two methods in a tight loop for every row ingested.
- **`WriteToServerAsync(DbDataReader, ct)`**: Pass the `DbDataReader` instance directly. Do NOT construct a `DataTable` or call any non-existent `WriteRowsAsync` method.
- **`EnableStreaming = true`**: Activates streaming mode on the bulk copy session — required when the source is a `DbDataReader` rather than a `DataTable`.
- **ColumnMappings**: `ColumnMappings.Add(name, name)` maps the reader's `GetName(ordinal)` return values to the SQL Server destination column names, decoupling ordinal position from physical column order.

