CREATE OR ALTER PROCEDURE dbo.usp_Chem_DispenseReagentFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @ChemicalCas    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        DrumId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(LitresAvailable), 0.00)
        FROM dbo.ReagentDrums WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND ChemicalCas = @ChemicalCas
          AND LitresAvailable > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                DrumId,
                LitresAvailable,
                SUM(LitresAvailable) OVER (
                    ORDER BY SynthesisDate ASC, DrumId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.ReagentDrums WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND ChemicalCas = @ChemicalCas
              AND LitresAvailable > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                DrumId,
                LitresAvailable,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN LitresAvailable
                    ELSE LitresAvailable - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - LitresAvailable < @RequiredQty
        )
        INSERT INTO @AllocatedLots (DrumId, AllocatedUnits)
        SELECT DrumId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.LitresAvailable = target.LitresAvailable - alloc.AllocatedUnits
        FROM dbo.ReagentDrums target
        INNER JOIN @AllocatedLots alloc ON target.DrumId = alloc.DrumId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

