            init() {
                this.searchInput.addEventListener('input', () => this.renderFiltered());
                this.warehouseSelect.addEventListener('change', () => this.renderFiltered());
                this.form.addEventListener('submit', (e) => this.handleAdjustment(e));
                this.loadData();
            }

            async loadData() {
                try {
                    const res = await fetch('/api/v1/erp/inventory/ledger', {
                        headers: { 'X-Tenant-ID': '00000000-0000-0000-0000-000000000001' }
                    });
                    this.items = res.ok ? await res.json() : [];
                    this.updateKpis();
                    this.renderFiltered();
                } catch {
                    this.tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-danger">Failed to load inventory.</td></tr>';
                }
            }

            updateKpis() {
                const totalUnits = this.items.reduce((sum, i) => sum + (i.onHandQty || 0), 0);
                const totalVal = this.items.reduce((sum, i) => sum + ((i.onHandQty || 0) * (i.unitCost || 0)), 0);
                const lowStock = this.items.filter(i => i.onHandQty <= i.reorderThreshold).length;

                document.getElementById('kpiTotalUnits').textContent = totalUnits.toLocaleString();
                document.getElementById('kpiTotalValuation').textContent = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(totalVal);
                document.getElementById('kpiLowStockCount').textContent = lowStock;
            }

            renderFiltered() {
                const kw = this.searchInput.value.toLowerCase();
                const wh = this.warehouseSelect.value;

                const filtered = this.items.filter(i => {
                    const matchKw = !kw || i.sku.toLowerCase().includes(kw) || i.description.toLowerCase().includes(kw);
                    const matchWh = !wh || i.warehouseId.toString() === wh;
                    return matchKw && matchWh;
                });

                if (!filtered.length) {
                    this.tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-muted">No matching inventory items.</td></tr>';
                    return;
                }

                this.tbody.innerHTML = filtered.map(i => `
                    <tr>
                        <td class="fw-bold text-primary">${i.sku}</td>
                        <td>${i.description}</td>
                        <td><span class="badge bg-light text-dark border">WH-0${i.warehouseId}</span></td>
                        <td class="text-end fw-semibold">${i.onHandQty.toLocaleString()}</td>
                        <td class="text-end">${new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(i.unitCost)}</td>
                        <td class="text-end fw-bold">${new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(i.onHandQty * i.unitCost)}</td>
                        <td><span class="badge ${i.onHandQty > i.reorderThreshold ? 'bg-success' : 'bg-warning'}">${i.onHandQty > i.reorderThreshold ? 'In Stock' : 'Low Stock'}</span></td>
                    </tr>
                `).join('');
            }

            async handleAdjustment(e) {
                e.preventDefault();
                const payload = {
                    sku: document.getElementById('adjSku').value,
                    warehouseId: parseInt(document.getElementById('adjWarehouse').value),
                    quantity: parseFloat(document.getElementById('adjQty').value)
                };

                await fetch('/api/v1/erp/inventory/adjustments', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Tenant-ID': '00000000-0000-0000-0000-000000000001' },
                    body: JSON.stringify(payload)
                });

                bootstrap.Modal.getInstance(document.getElementById('adjustmentModal')).hide();
                await this.loadData();
            }
        }

        const app = new InventoryLedgerApp();
    </script>
