### 1. SQL Server T-SQL Schema & Sproc (`dbo.GlJournalEntries`)
```sql
CREATE TABLE dbo.GlJournalEntries
(
    EntryId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_GlJournalEntries_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    PostingStatus   NVARCHAR(50)     NOT NULL,
    TotalDebitAmount      DECIMAL(18, 2)   NOT NULL,
    CreatedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_GlJournalEntries_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_GlJournalEntries PRIMARY KEY CLUSTERED (EntryId)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_ERP_CreateJournalEntry
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.GlJournalEntries (EntryId, TenantId, PostingStatus, TotalDebitAmount)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

