- Scalar Output Assignment: Generates NEWID() explicitly in T-SQL and returns via OUTPUT parameter.
- Clean Parameter Direction: Avoids scalar OUTPUT INTO syntax bugs.
- Minimal API Typed Results: Employs typed Result unions and claims extraction.

Here is the complete .NET 10 Minimal API implementation for 'BMS Timesheet Submission & Lock':

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Routing;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;

namespace EnterpriseBMS.Api.Endpoints;

public sealed record BmsTimesheetResult(Guid Id, string Status, DateTimeOffset ProcessedAtUtc);

public static class BmsTimesheetEndpoints
{
    public static RouteGroupBuilder MapBmsTimesheetEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/bms/timesheets")
            .WithTags("BMS Timesheet Submission & Lock")
            .RequireAuthorization();

        group.MapPost("/{id:guid}/process",
            async Task<Results<Ok<BmsTimesheetResult>, NotFound, Conflict, BadRequest<ProblemDetails>>> (
                Guid id,
                IBmsTimesheetService service,
                ILogger<BmsTimesheetEndpoints> logger,
                CancellationToken ct) =>
            {
                logger.LogInformation("Processing {EntityId} for BMS Timesheet Submission & Lock", id);
                try
                {
                    var result = await service.ProcessAsync(id, ct);
                    return result is null
                        ? TypedResults.NotFound()
                        : TypedResults.Ok(result);
                }
                catch (SqlException ex) when (ex.Number == 54001)
                {
                    logger.LogWarning(ex, "Conflict on BMS Timesheet Submission & Lock: SqlError {Number}", ex.Number);
                    return TypedResults.Conflict(new ProblemDetails
                    {
                        Title  = "State Conflict",
                        Detail = ex.Message,
                        Status = StatusCodes.Status409Conflict
                    });
                }
                catch (SqlException ex) when (ex.Number == 54002)
                {
                    logger.LogWarning(ex, "Validation failure on BMS Timesheet Submission & Lock: SqlError {Number}", ex.Number);
                    return TypedResults.BadRequest(new ProblemDetails
                    {
                        Title  = "Business Rule Violation",
                        Detail = ex.Message,
                        Status = StatusCodes.Status400BadRequest
                    });
                }
            })
        // AddEndpointFilter<T>() is chained directly on the route — not on the group.
        // This registers TenantContextFilter as the outermost pipeline step.
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("ProcessBmsTimesheet")
        .Produces<BmsTimesheetResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound)
        .ProducesProblem(StatusCodes.Status409Conflict)
        .ProducesValidationProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}

public interface IBmsTimesheetService
{
    Task<BmsTimesheetResult?> ProcessAsync(Guid id, CancellationToken ct);
}
```

### Key Architectural Highlights:
- AddEndpointFilter<TenantContextFilter>(): chained via `.AddEndpointFilter<T>()` directly on the route — validates the X-Tenant-ID header before the handler executes.
- SqlException routing: `when (ex.Number == 54001)` → 409 Conflict; `when (ex.Number == 54002)` → 400 BadRequest — both return RFC 7807 ProblemDetails.
- TypedResults union: `Results<Ok<BmsTimesheetResult>, NotFound, Conflict, BadRequest<ProblemDetails>>` is compile-time verified.

