namespace Enterprise.IntercompanyBilling.Infrastructure.Data;

public sealed record TransferPricingPostingLineDto(
    string AccountNumber,
    char PostingDirection,
    string CurrencyCode,
    decimal FxRate,
    decimal AmountInCurrency
);

public sealed class TransferPricingPostingRepository
{
    private readonly string _connectionString;

    public TransferPricingPostingRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<Guid> PostJournalAsync(
        Guid tenantId,
        string referenceNumber,
        IEnumerable<TransferPricingPostingLineDto> lines,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_TransferPricingPosting", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@ReferenceNumber", SqlDbType.NVarChar, 50) { Value = referenceNumber });

        var dt = new DataTable();
        dt.Columns.Add("AccountNumber", typeof(string));
        dt.Columns.Add("PostingDirection", typeof(string));
        dt.Columns.Add("CurrencyCode", typeof(string));
        dt.Columns.Add("FxRate", typeof(decimal));
        dt.Columns.Add("AmountInCurrency", typeof(decimal));

        foreach (var line in lines)
        {
            dt.Rows.Add(
                line.AccountNumber,
                line.PostingDirection.ToString(),
                line.CurrencyCode,
                line.FxRate,
                line.AmountInCurrency
            );
        }

        var tvpParam = new SqlParameter("@Lines", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_TransferPricingPostingLine",
            Value = dt
        };
        command.Parameters.Add(tvpParam);

        var outParam = new SqlParameter("@CreatedEntryId", SqlDbType.UniqueIdentifier)
        {
            Direction = ParameterDirection.Output
        };
        command.Parameters.Add(outParam);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        return outParam.Value is Guid id ? id : throw new InvalidOperationException("Failed to retrieve created EntryId from database.");
    }
}
