Here is the complete enterprise hierarchical Bill of Materials (BOM) explosion architecture:

### 1. SQL Server T-SQL Database Tier (`Databases/MesDb/Scripts/BomSchema.sql`)
```sql
CREATE TABLE dbo.PartsCatalog
(
    PartId          UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_PartsCatalog_Id DEFAULT NEWSEQUENTIALID(),
    TenantId        UNIQUEIDENTIFIER NOT NULL,
    PartNumber      NVARCHAR(50)     NOT NULL,
    PartName        NVARCHAR(200)    NOT NULL,
    UnitOfMeasure   NVARCHAR(20)     NOT NULL,
    StandardCost    DECIMAL(18, 4)   NOT NULL CHECK (StandardCost >= 0.0000),
    IsAssembly      BIT              NOT NULL CONSTRAINT DF_PartsCatalog_Assembly DEFAULT 0,
    CONSTRAINT PK_PartsCatalog PRIMARY KEY CLUSTERED (PartId),
    CONSTRAINT UQ_PartsCatalog_Number UNIQUE (TenantId, PartNumber)
);
GO

CREATE TABLE dbo.BillOfMaterials
(
    BomId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_BOM_Id DEFAULT NEWSEQUENTIALID(),
    TenantId        UNIQUEIDENTIFIER NOT NULL,
    ParentPartId    UNIQUEIDENTIFIER NOT NULL,
    ComponentPartId UNIQUEIDENTIFIER NOT NULL,
    QuantityPer     DECIMAL(18, 4)   NOT NULL CHECK (QuantityPer > 0.0000),
    ScrapFactorPct  DECIMAL(5, 2)    NOT NULL CONSTRAINT DF_BOM_Scrap DEFAULT 0.00 CHECK (ScrapFactorPct >= 0.00),
    CONSTRAINT PK_BillOfMaterials PRIMARY KEY CLUSTERED (BomId),
    CONSTRAINT FK_BOM_Parent FOREIGN KEY (ParentPartId) REFERENCES dbo.PartsCatalog (PartId),
    CONSTRAINT FK_BOM_Component FOREIGN KEY (ComponentPartId) REFERENCES dbo.PartsCatalog (PartId),
    CONSTRAINT CK_BOM_NoSelfRef CHECK (ParentPartId <> ComponentPartId)
);
GO

CREATE NONCLUSTERED INDEX IX_BillOfMaterials_ParentLookup
ON dbo.BillOfMaterials (TenantId, ParentPartId)
INCLUDE (ComponentPartId, QuantityPer, ScrapFactorPct);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Mes_ExplodeBillOfMaterials
    @TenantId      UNIQUEIDENTIFIER,
    @RootPartId    UNIQUEIDENTIFIER,
    @BuildQuantity DECIMAL(18, 4) = 1.0000,
    @MaxDepth      INT = 20
AS
BEGIN
    SET NOCOUNT ON;

    -- Recursive CTE with Hierarchical Level Tracking and Cycle Prevention
    WITH BomExplosion AS
    (
        -- Anchor Member: Root Assembly Level 0
        SELECT 
            p.PartId,
            p.PartNumber,
            p.PartName,
            p.UnitOfMeasure,
            p.StandardCost,
            p.IsAssembly,
            CAST(1.0000 AS DECIMAL(18, 4)) AS UnitQuantityRequired,
            CAST(@BuildQuantity AS DECIMAL(18, 4)) AS TotalQuantityRequired,
            0 AS HierarchyLevel,
            CAST(CONCAT('/', CAST(p.PartId AS VARCHAR(36)), '/') AS VARCHAR(MAX)) AS NodePath
        FROM dbo.PartsCatalog p
        WHERE p.TenantId = @TenantId AND p.PartId = @RootPartId

        UNION ALL

        -- Recursive Member: Subcomponents and Child Assemblies
        SELECT 
            c.PartId,
            c.PartNumber,
            c.PartName,
            c.UnitOfMeasure,
            c.StandardCost,
            c.IsAssembly,
            CAST(parent.UnitQuantityRequired * bom.QuantityPer * (1.0 + (bom.ScrapFactorPct / 100.0)) AS DECIMAL(18, 4)) AS UnitQuantityRequired,
            CAST(parent.TotalQuantityRequired * bom.QuantityPer * (1.0 + (bom.ScrapFactorPct / 100.0)) AS DECIMAL(18, 4)) AS TotalQuantityRequired,
            parent.HierarchyLevel + 1 AS HierarchyLevel,
            CAST(CONCAT(parent.NodePath, CAST(c.PartId AS VARCHAR(36)), '/') AS VARCHAR(MAX)) AS NodePath
        FROM BomExplosion parent
        INNER JOIN dbo.BillOfMaterials bom ON parent.PartId = bom.ParentPartId AND bom.TenantId = @TenantId
        INNER JOIN dbo.PartsCatalog c ON bom.ComponentPartId = c.PartId
        WHERE parent.HierarchyLevel < @MaxDepth
          AND parent.NodePath NOT LIKE CONCAT('%/', CAST(c.PartId AS VARCHAR(36)), '/%') -- Cycle prevention
    )
    SELECT 
        PartId,
        PartNumber,
        PartName,
        UnitOfMeasure,
        StandardCost,
        IsAssembly,
        UnitQuantityRequired,
        TotalQuantityRequired,
        HierarchyLevel
    FROM BomExplosion
    ORDER BY HierarchyLevel ASC, PartNumber ASC
    OPTION (MAXRECURSION 100);
END;
GO
```

