using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseMes.Infrastructure.Data;

public sealed record BomComponentExplosionDto(
    Guid PartId,
    string PartNumber,
    string PartName,
    string UnitOfMeasure,
    decimal StandardCost,
    bool IsAssembly,
    decimal UnitQuantityRequired,
    decimal TotalQuantityRequired,
    int HierarchyLevel
);

public sealed class ManufacturingBomRepository
{
    private readonly string _connectionString;

    public ManufacturingBomRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<BomComponentExplosionDto> StreamExplodedBomAsync(
        Guid tenantId,
        Guid rootPartId,
        decimal buildQuantity,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Mes_ExplodeBillOfMaterials", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@RootPartId", SqlDbType.UniqueIdentifier) { Value = rootPartId });
        command.Parameters.Add(new SqlParameter("@BuildQuantity", SqlDbType.Decimal) { Precision = 18, Scale = 4, Value = buildQuantity });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordId = reader.GetOrdinal("PartId");
        int ordNum = reader.GetOrdinal("PartNumber");
        int ordName = reader.GetOrdinal("PartName");
        int ordUom = reader.GetOrdinal("UnitOfMeasure");
        int ordCost = reader.GetOrdinal("StandardCost");
        int ordIsAssy = reader.GetOrdinal("IsAssembly");
        int ordUnitQty = reader.GetOrdinal("UnitQuantityRequired");
        int ordTotalQty = reader.GetOrdinal("TotalQuantityRequired");
        int ordLevel = reader.GetOrdinal("HierarchyLevel");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new BomComponentExplosionDto(
                PartId: reader.GetGuid(ordId),
                PartNumber: reader.GetString(ordNum),
                PartName: reader.GetString(ordName),
                UnitOfMeasure: reader.GetString(ordUom),
                StandardCost: reader.GetDecimal(ordCost),
                IsAssembly: reader.GetBoolean(ordIsAssy),
                UnitQuantityRequired: reader.GetDecimal(ordUnitQty),
                TotalQuantityRequired: reader.GetDecimal(ordTotalQty),
                HierarchyLevel: reader.GetInt32(ordLevel)
            );
        }
    }
}
