            .RequireAuthorization();

        group.MapGet("/assemblies/{partId:guid}/explode", async Task<Results<Ok<IReadOnlyList<BomComponentExplosionDto>>, BadRequest<ProblemDetails>>> (
            Guid partId,
            Guid tenantId,
            decimal? buildQuantity,
            ManufacturingBomRepository repository,
            CancellationToken cancellationToken) =>
        {
            decimal qty = buildQuantity ?? 1.0000m;
            if (qty <= 0)
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Invalid Build Quantity",
                    Detail = "Build quantity must be greater than zero."
                });
            }

            var list = new List<BomComponentExplosionDto>();
            await foreach (var item in repository.StreamExplodedBomAsync(tenantId, partId, qty, cancellationToken))
            {
                list.Add(item);
            }

            return TypedResults.Ok<IReadOnlyList<BomComponentExplosionDto>>(list);
        })
        .WithName("ExplodeBillOfMaterials")
        .Produces<IReadOnlyList<BomComponentExplosionDto>>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}
