- **Recursive Hierarchy Traversal**: Employs T-SQL recursive Common Table Expressions with string path cycle prevention (`NodePath NOT LIKE ...`) to safely resolve deep assembly trees without infinite loops.
- **Scrap Factor Compounding**: Quantities dynamically compound scrap factors across intermediate parent-child relationships in a single pass.
- **Asynchronous O(1) Memory Streaming**: Uses ADO.NET `SequentialAccess` and `IAsyncEnumerable<T>` to stream massive multi-thousand part BOM structures directly to the client without buffering entire datasets into memory.

Here is the complete production-ready C# .NET 10 ADO.NET repository class for 'BMS Resource Allocation' entity `BmsResourceAssignment` using Microsoft.Data.SqlClient:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseDomain.Infrastructure.Data;

public sealed record BmsResourceAssignmentDto(
    Guid AssignmentId,
    Guid TenantId,
    string ResourceRole,
    decimal AllocatedHours,
    DateTimeOffset CreatedAtUtc
);

public sealed class BmsResourceAssignmentRepository
{
    private readonly string _connectionString;

    public BmsResourceAssignmentRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Inserts a new BmsResourceAssignment record and returns the generated UUID atomically.
    /// </summary>
    public async Task<Guid> CreateAsync(BmsResourceAssignmentDto dto, CancellationToken cancellationToken = default)
    {
        const string sql = @"
            INSERT INTO dbo.BmsResourceAssignments (
                TenantId, 
                ResourceRole, 
                AllocatedHours, 
                CreatedAtUtc
            )
            OUTPUT inserted.AssignmentId
            VALUES (
                @TenantId, 
                @ResourceRole, 
                @AllocatedHours, 
                SYSUTCDATETIME()
            );";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = dto.TenantId });
        command.Parameters.Add(new SqlParameter("@ResourceRole", SqlDbType.NVarChar, 50) { Value = dto.ResourceRole });

        var numParam = new SqlParameter("@AllocatedHours", SqlDbType.Decimal)
        {
            Precision = 18,
            Scale = 2,
            Value = dto.AllocatedHours
        };
        command.Parameters.Add(numParam);

        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return (Guid)result!;
    }

    /// <summary>
    /// Streams paginated BmsResourceAssignment records without materializing full lists in RAM.
    /// </summary>
    public async IAsyncEnumerable<BmsResourceAssignmentDto> StreamPagedAsync(
        Guid tenantId,
        int pageNumber,
        int pageSize,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                AssignmentId, 
                TenantId, 
                ResourceRole, 
                AllocatedHours, 
                CreatedAtUtc
            FROM dbo.BmsResourceAssignments WITH (READPAST)
            WHERE TenantId = @TenantId
            ORDER BY CreatedAtUtc DESC
            OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Offset", SqlDbType.Int) { Value = (pageNumber - 1) * pageSize });
        command.Parameters.Add(new SqlParameter("@PageSize", SqlDbType.Int) { Value = pageSize });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection, 
            cancellationToken
        ).ConfigureAwait(false);

        int ordId = reader.GetOrdinal("AssignmentId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("ResourceRole");
        int ordNum = reader.GetOrdinal("AllocatedHours");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new BmsResourceAssignmentDto(
                AssignmentId: reader.GetGuid(ordId),
                TenantId: reader.GetGuid(ordTenant),
                ResourceRole: reader.GetString(ordStatus),
                AllocatedHours: reader.GetDecimal(ordNum),
                CreatedAtUtc: reader.GetDateTimeOffset(ordCreated)
            );
        }
    }

    /// <summary>
    /// Updates status atomically under Snapshot Isolation to prevent read blocking.
    /// </summary>
    public async Task<bool> UpdateStatusAsync(
        Guid AssignmentId, 
        string newStatus, 
        CancellationToken cancellationToken = default)
    {
        const string sql = @"
            UPDATE dbo.BmsResourceAssignments
            SET ResourceRole = @NewStatus
            WHERE AssignmentId = @AssignmentId;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(
            IsolationLevel.Snapshot, 
            cancellationToken
        ).ConfigureAwait(false);

        try
        {
            await using var command = new SqlCommand(sql, connection, transaction);
            command.Parameters.Add(new SqlParameter("@AssignmentId", SqlDbType.UniqueIdentifier) { Value = AssignmentId });
            command.Parameters.Add(new SqlParameter("@NewStatus", SqlDbType.NVarChar, 50) { Value = newStatus });

            int affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return affected > 0;
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }
}
```

### Key Architectural Highlights:
- Identity Retrieval: Retrieves the generated UUID atomically upon insertion via OUTPUT inserted.AssignmentId.
- Memory-Efficient Streaming: Streams paginated `BmsResourceAssignmentDto` records asynchronously using IAsyncEnumerable with SequentialAccess.
- Snapshot Isolation: Executes atomic status updates under Snapshot isolation to prevent read blocking.

