                <h2 class="fw-bold text-dark mb-0">ERP JournalEntry Console</h2>
                <p class="text-muted small">Manage JournalEntry records and workflow transitions.</p>
            </div>
            <button id="btnRefresh" class="btn btn-primary">Refresh Data</button>
        </div>

        <div class="card card-custom bg-white p-4">
            <div class="table-responsive">
                <table class="table table-hover align-middle mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Identifier</th>
                            <th>Status</th>
                            <th>Value</th>
                            <th class="text-end">Actions</th>
                        </tr>
                    </thead>
                    <tbody id="tableBody">
                        <tr><td colspan="4" class="text-center py-4 text-muted">Loading data...</td></tr>
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <script>
        const tbody = document.getElementById('tableBody');
        const token = localStorage.getItem('auth_token') || 'demo_token';
        const tenantId = localStorage.getItem('tenant_id') || '00000000-0000-0000-0000-000000000001';

        async function loadRecords() {
            try {
                const res = await fetch('/api/v1/erp/journalentrys', {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'X-Tenant-Id': tenantId,
                        'Accept': 'application/json'
                    }
                });
                if (!res.ok) throw new Error('Network error');
                const items = await res.json();
                render(items);
            } catch (err) {
                tbody.innerHTML = `<tr><td colspan="4" class="text-center text-danger py-4">${err.message}</td></tr>`;
            }
        }

        function render(items) {
            if (!items || items.length === 0) {
                tbody.innerHTML = '<tr><td colspan="4" class="text-center text-muted py-4">No records found.</td></tr>';
                return;
            }
            const formatter = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
