                    <td class="text-end">
                        <button class="btn btn-sm btn-outline-secondary" onclick="viewDetails('${x.entryid}')">View</button>
                    </td>
                </tr>
            `).join('');
        }

        document.getElementById('btnRefresh').addEventListener('click', loadRecords);
        loadRecords();
    </script>
</body>
</html>
