Here is the complete, production-grade SQL implementation:

```sql
CREATE OR ALTER PROCEDURE dbo.usp_Agri_DispenseGrainFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @GrainType    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        SiloLotId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(BushelsRemaining), 0.00)
        FROM dbo.GrainLots WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND GrainType = @GrainType
          AND BushelsRemaining > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                SiloLotId,
                BushelsRemaining,
                SUM(BushelsRemaining) OVER (
                    ORDER BY HarvestDate ASC, SiloLotId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.GrainLots WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND GrainType = @GrainType
              AND BushelsRemaining > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                SiloLotId,
                BushelsRemaining,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN BushelsRemaining
                    ELSE BushelsRemaining - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - BushelsRemaining < @RequiredQty
        )
        INSERT INTO @AllocatedLots (SiloLotId, AllocatedUnits)
        SELECT SiloLotId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.BushelsRemaining = target.BushelsRemaining - alloc.AllocatedUnits
        FROM dbo.GrainLots target
        INNER JOIN @AllocatedLots alloc ON target.SiloLotId = alloc.SiloLotId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

