    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
    <script>
        class TimesheetController {
            constructor() {
                this.tbody = document.getElementById('tableBody');
                this.filterKeyword = document.getElementById('filterKeyword');
                this.filterStatus = document.getElementById('filterStatus');
                this.form = document.getElementById('createForm');
                this.items = [];
                this.init();
            }

            async init() {
                document.getElementById('btnFilter').addEventListener('click', () => this.applyFilter());
                this.form.addEventListener('submit', (e) => this.handleSubmit(e));
                await this.fetchData();
            }

            async fetchData() {
                try {
                    const res = await fetch('/api/v1/bms/timesheets');
                    this.items = res.ok ? await res.json() : [];
                    this.render(this.items);
                } catch {
                    this.tbody.innerHTML = '<tr><td colspan="6" class="text-center py-4 text-danger">Failed to load data.</td></tr>';
                }
            }

            render(records) {
                if (!records.length) {
                    this.tbody.innerHTML = '<tr><td colspan="6" class="text-center py-4 text-muted">No records found.</td></tr>';
                    return;
                }
                this.tbody.innerHTML = records.map(r => `
                    <tr>
                        <td class="fw-semibold text-primary">#${r.id.substring(0,8)}</td>
                        <td>${r.name}</td>
                        <td><span class="badge bg-secondary">${r.status}</span></td>
                        <td>${new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(r.amount || 0)}</td>
                        <td>${new Date(r.createdAtUtc).toLocaleDateString()}</td>
                        <td class="text-end">
                            <button class="btn btn-sm btn-outline-primary" onclick="controller.edit('${r.id}')">Edit</button>
                        </td>
                    </tr>
                `).join('');
            }

            applyFilter() {
                const kw = this.filterKeyword.value.toLowerCase();
                const st = this.filterStatus.value;
                const filtered = this.items.filter(i => 
                    (!kw || i.name.toLowerCase().includes(kw)) &&
                    (!st || i.status === st)
                );
                this.render(filtered);
            }

            async handleSubmit(e) {
                e.preventDefault();
                const payload = {
                    name: document.getElementById('inputName').value,
                    status: document.getElementById('inputStatus').value
                };
                await fetch('/api/v1/bms/timesheets', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                bootstrap.Modal.getInstance(document.getElementById('createModal')).hide();
                await this.fetchData();
            }

            edit(id) { console.log('Editing', id); }
        }

        const controller = new TimesheetController();
    </script>
</body>
</html>
