```sql
CREATE TABLE dbo.BmsTimesheets
(
    TimesheetId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_BmsTimesheets_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    ApprovalStatus   NVARCHAR(50)     NOT NULL,
    TotalBillableHours      DECIMAL(18, 2)   NOT NULL,
    CreatedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_BmsTimesheets_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_BmsTimesheets PRIMARY KEY CLUSTERED (TimesheetId)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_BMS_CreateTimesheetBatch
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.BmsTimesheets (TimesheetId, TenantId, ApprovalStatus, TotalBillableHours)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### 2. C# .NET 10 ADO.NET Repository (`TimesheetBatchRepository.cs`)
```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.BMS.Infrastructure.Data;

public sealed class TimesheetBatchRepository
{
