    public TimesheetBatchRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<Guid> CreateAsync(Guid tenantId, string status, decimal value, CancellationToken ct)
    {
        await using var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync(ct).ConfigureAwait(false);

        await using var cmd = new SqlCommand("dbo.usp_BMS_CreateTimesheetBatch", conn)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        cmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        cmd.Parameters.Add(new SqlParameter("@Status", SqlDbType.NVarChar, 50) { Value = status });
        cmd.Parameters.Add(new SqlParameter("@Value", SqlDbType.Decimal) { Precision = 18, Scale = 2, Value = value });

        var outParam = new SqlParameter("@CreatedId", SqlDbType.UniqueIdentifier)
        {
            Direction = ParameterDirection.InputOutput,
            Value = DBNull.Value
        };
        cmd.Parameters.Add(outParam);

        await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
        return (Guid)outParam.Value;
    }
