    {
        var group = routes.MapGroup("/api/v1/bms/timesheetbatchs")
            .RequireAuthorization();

        group.MapPost("/", async Task<Results<Ok<CreateTimesheetBatchResponse>, BadRequest<ProblemDetails>>> (
            CreateTimesheetBatchRequest req,
