            var id = await repo.CreateAsync(tenantId, req.Status, req.Value, ct);
            return TypedResults.Ok(new CreateTimesheetBatchResponse(id));
        })
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("CreateTimesheetBatch")
        .Produces<CreateTimesheetBatchResponse>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}

