```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseCRM.Infrastructure.Data;

public readonly record struct CustomerRecord(
    Guid CustomerId,
    string AccountNumber,
    string CompanyName,
    decimal LifetimeValue,
    DateTimeOffset CreatedAtUtc,
    bool IsActive
);

public sealed class CustomerRepository
{
    private readonly string _connectionString;

    public CustomerRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Streams customer CRM records asynchronously with zero-allocation buffering using IAsyncEnumerable.
    /// Uses explicit parameter types to prevent query plan bloat and implicit type conversion in SQL Server.
    /// </summary>
    public async IAsyncEnumerable<CustomerRecord> StreamActiveCustomersByTierAsync(
        decimal minLifetimeValue,
        DateTimeOffset registeredAfterUtc,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                CustomerId,
                AccountNumber,
                CompanyName,
                LifetimeValue,
                CreatedAtUtc,
                IsActive
            FROM dbo.CrmCustomers WITH (NOLOCK)
            WHERE LifetimeValue >= @MinLifetimeValue
              AND CreatedAtUtc >= @RegisteredAfterUtc
              AND IsActive = 1
            ORDER BY LifetimeValue DESC;";

        // Ensure connection lifecycle is strictly bound to the asynchronous enumeration
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandType = CommandType.Text,
            CommandTimeout = 60
        };

        // Explicit parameter mapping prevents implicit conversion penalties and allows plan caching
        var paramLtv = new SqlParameter("@MinLifetimeValue", SqlDbType.Decimal)
        {
            Precision = 18,
            Scale = 2,
            Value = minLifetimeValue
        };

        var paramRegistered = new SqlParameter("@RegisteredAfterUtc", SqlDbType.DateTimeOffset)
        {
            Value = registeredAfterUtc
        };

        command.Parameters.Add(paramLtv);
        command.Parameters.Add(paramRegistered);

        // CommandBehavior.SequentialAccess minimizes memory overhead for large streams
        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        // Cache column ordinals to avoid repeated dictionary lookups inside the reader loop
        int ordCustomerId = reader.GetOrdinal("CustomerId");
        int ordAccountNumber = reader.GetOrdinal("AccountNumber");
        int ordCompanyName = reader.GetOrdinal("CompanyName");
        int ordLifetimeValue = reader.GetOrdinal("LifetimeValue");
        int ordCreatedAtUtc = reader.GetOrdinal("CreatedAtUtc");
        int ordIsActive = reader.GetOrdinal("IsActive");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new CustomerRecord(
                CustomerId: reader.GetGuid(ordCustomerId),
                AccountNumber: reader.GetString(ordAccountNumber),
                CompanyName: reader.GetString(ordCompanyName),
                LifetimeValue: reader.GetDecimal(ordLifetimeValue),
                CreatedAtUtc: reader.GetDateTimeOffset(ordCreatedAtUtc),
                IsActive: reader.GetBoolean(ordIsActive)
            );
        }
    }
}
```

