using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.Healthcare.Infrastructure.Data;

public sealed record PatientObservationBatchItem(
    string UnitOfMeasure,
    decimal MetricValue
);

public sealed class PatientObservationBatchService
{
    private readonly string _connectionString;

    public PatientObservationBatchService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<Guid?> CreateBatchAsync(
        Guid tenantId,
        Guid userId,
        IEnumerable<PatientObservationBatchItem> items,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Healthcare_CreatePatientObservationBatch", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@UserId", SqlDbType.UniqueIdentifier) { Value = userId });

        var dt = new DataTable();
        dt.Columns.Add("UnitOfMeasure", typeof(string));
        dt.Columns.Add("MetricValue", typeof(decimal));

        foreach (var item in items)
        {
            dt.Rows.Add(item.UnitOfMeasure, item.MetricValue);
        }

        var tvpParam = new SqlParameter("@Items", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_PatientObservationBatchItem",
            Value = dt
        };
        command.Parameters.Add(tvpParam);

        var outParam = new SqlParameter("@CreatedBatchId", SqlDbType.UniqueIdentifier)
        {
            Direction = ParameterDirection.Output
        };
        command.Parameters.Add(outParam);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        return outParam.Value is Guid id ? id : null;
    }
}
