### 1. SQL Server T-SQL Schema & Sproc (`dbo.BmsBudgetLines`)
```sql
CREATE TABLE dbo.BmsBudgetLines
(
    BudgetLineId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_BmsBudgetLines_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    VarianceStatus   NVARCHAR(50)     NOT NULL,
    AllocatedCost      DECIMAL(18, 2)   NOT NULL,
    CreatedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_BmsBudgetLines_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_BmsBudgetLines PRIMARY KEY CLUSTERED (BudgetLineId)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_BMS_CreateProjectBudgetLine
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.BmsBudgetLines (BudgetLineId, TenantId, VarianceStatus, AllocatedCost)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

