Here is the high-performance C# .NET 10 ADO.NET streaming implementation for Healthcare entity `PatientEncounter`:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.Healthcare.Infrastructure.Data;

public readonly record struct PatientEncounterSummary(
    Guid EncounterId,
    Guid TenantId,
    string EncounterStatus,
    decimal TotalClaimCharges,
    DateTimeOffset CreatedAtUtc
);

public sealed class PatientEncounterQueryRepository
{
    private readonly string _connectionString;

    public PatientEncounterQueryRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<PatientEncounterSummary> StreamByStatusAsync(
        Guid tenantId,
        string status,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                EncounterId,
                TenantId,
                EncounterStatus,
                TotalClaimCharges,
                CreatedAtUtc
            FROM dbo.EhrPatientEncounters WITH (READPAST)
            WHERE TenantId = @TenantId
              AND EncounterStatus = @Status
            ORDER BY CreatedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Status", SqlDbType.NVarChar, 50) { Value = status });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordPk = reader.GetOrdinal("EncounterId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("EncounterStatus");
        int ordVal = reader.GetOrdinal("TotalClaimCharges");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new PatientEncounterSummary(
                EncounterId: reader.GetGuid(ordPk),
                TenantId: reader.GetGuid(ordTenant),
                EncounterStatus: reader.GetString(ordStatus),
                TotalClaimCharges: reader.GetDecimal(ordVal),
                CreatedAtUtc: reader.GetDateTime(ordCreated)
            );
        }
    }
}
```

### Key Architectural Highlights:
- SequentialAccess: Employs sequential streaming to eliminate client memory buffering.
- Ordinal Caching: Caches column ordinals outside the read loop for maximum throughput.
- Cancellation Propagation: Forwards the CancellationToken directly to all async ADO.NET calls.

Here is the complete, production-grade SQL implementation:

```sql
CREATE OR ALTER PROCEDURE dbo.usp_Brewery_ShipKegsFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @BeerStyle    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        KegLotId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(KegsAvailable), 0.00)
        FROM dbo.KegInventory WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND BeerStyle = @BeerStyle
          AND KegsAvailable > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                KegLotId,
                KegsAvailable,
                SUM(KegsAvailable) OVER (
                    ORDER BY BrewDate ASC, KegLotId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.KegInventory WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND BeerStyle = @BeerStyle
              AND KegsAvailable > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                KegLotId,
                KegsAvailable,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN KegsAvailable
                    ELSE KegsAvailable - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - KegsAvailable < @RequiredQty
        )
        INSERT INTO @AllocatedLots (KegLotId, AllocatedUnits)
        SELECT KegLotId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.KegsAvailable = target.KegsAvailable - alloc.AllocatedUnits
        FROM dbo.KegInventory target
        INNER JOIN @AllocatedLots alloc ON target.KegLotId = alloc.KegLotId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

