```sql
CREATE OR ALTER PROCEDURE dbo.usp_Auto_AllocateFastenersFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @FastenerSpec    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        FastenerLotId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(QuantityOnHand), 0.00)
        FROM dbo.FastenerLots WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND FastenerSpec = @FastenerSpec
          AND QuantityOnHand > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                FastenerLotId,
                QuantityOnHand,
                SUM(QuantityOnHand) OVER (
                    ORDER BY ArrivalDateUtc ASC, FastenerLotId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.FastenerLots WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND FastenerSpec = @FastenerSpec
              AND QuantityOnHand > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                FastenerLotId,
                QuantityOnHand,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN QuantityOnHand
                    ELSE QuantityOnHand - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - QuantityOnHand < @RequiredQty
        )
        INSERT INTO @AllocatedLots (FastenerLotId, AllocatedUnits)
        SELECT FastenerLotId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.QuantityOnHand = target.QuantityOnHand - alloc.AllocatedUnits
        FROM dbo.FastenerLots target
        INNER JOIN @AllocatedLots alloc ON target.FastenerLotId = alloc.FastenerLotId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

