CREATE OR ALTER PROCEDURE dbo.usp_Meat_ProcessLotFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @CutGrade    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        CarcassLotId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(WeightKgRemaining), 0.00)
        FROM dbo.ColdStorageCarcasses WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND CutGrade = @CutGrade
          AND WeightKgRemaining > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                CarcassLotId,
                WeightKgRemaining,
                SUM(WeightKgRemaining) OVER (
                    ORDER BY IntakeDate ASC, CarcassLotId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.ColdStorageCarcasses WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND CutGrade = @CutGrade
              AND WeightKgRemaining > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                CarcassLotId,
                WeightKgRemaining,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN WeightKgRemaining
                    ELSE WeightKgRemaining - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - WeightKgRemaining < @RequiredQty
        )
        INSERT INTO @AllocatedLots (CarcassLotId, AllocatedUnits)
        SELECT CarcassLotId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.WeightKgRemaining = target.WeightKgRemaining - alloc.AllocatedUnits
        FROM dbo.ColdStorageCarcasses target
        INNER JOIN @AllocatedLots alloc ON target.CarcassLotId = alloc.CarcassLotId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
