```sql
CREATE OR ALTER PROCEDURE dbo.usp_Pharma_AllocateDosesFifo
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @VaccineCode    NVARCHAR(50),
    @RequiredQty   DECIMAL(18, 2),
    @AllocatedQty  DECIMAL(18, 2) OUTPUT,
    @RemainingQty  DECIMAL(18, 2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RequiredQty <= 0.00
    BEGIN
        THROW 51001, 'Required Quantity must be strictly greater than zero.', 1;
        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        BatchId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(AvailableDoses), 0.00)
        FROM dbo.VaccineBatches WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND VaccineCode = @VaccineCode
          AND AvailableDoses > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                BatchId,
                AvailableDoses,
                SUM(AvailableDoses) OVER (
                    ORDER BY ManufacturedDate ASC, BatchId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.VaccineBatches WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND VaccineCode = @VaccineCode
              AND AvailableDoses > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                BatchId,
                AvailableDoses,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN AvailableDoses
                    ELSE AvailableDoses - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - AvailableDoses < @RequiredQty
        )
        INSERT INTO @AllocatedLots (BatchId, AllocatedUnits)
        SELECT BatchId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.AvailableDoses = target.AvailableDoses - alloc.AllocatedUnits
        FROM dbo.VaccineBatches target
        INNER JOIN @AllocatedLots alloc ON target.BatchId = alloc.BatchId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

