Here is the complete production-grade enterprise architecture for an ERP FIFO Inventory Valuation and Consumption engine:

### 1. SQL Server Database Schema (Batches & Queue Index)
```sql
CREATE TABLE dbo.ErpInventoryBatches
(
    BatchId             UNIQUEIDENTIFIER    NOT NULL CONSTRAINT DF_ErpBatches_Id DEFAULT NEWSEQUENTIALID(),
    TenantId            UNIQUEIDENTIFIER    NOT NULL,
    ItemSku             NVARCHAR(50)        NOT NULL,
    WarehouseId         INT                 NOT NULL,
    ReceivedDateUtc     DATETIME2(7)        NOT NULL,
    InitialQuantity     DECIMAL(18, 4)      NOT NULL,
    RemainingQuantity   DECIMAL(18, 4)      NOT NULL,
    UnitCost            DECIMAL(18, 4)      NOT NULL,
    IsExhausted         BIT                 NOT NULL CONSTRAINT DF_ErpBatches_Exhausted DEFAULT 0,
    CreatedAtUtc        DATETIME2(7)        NOT NULL CONSTRAINT DF_ErpBatches_Created DEFAULT SYSUTCDATETIME(),

    CONSTRAINT PK_ErpInventoryBatches PRIMARY KEY CLUSTERED (BatchId),
    CONSTRAINT CK_ErpInventoryBatches_Qty CHECK (RemainingQuantity >= 0)
);

CREATE NONCLUSTERED INDEX IX_ErpInventoryBatches_FifoQueue
ON dbo.ErpInventoryBatches (TenantId, ItemSku, WarehouseId, ReceivedDateUtc ASC)
INCLUDE (RemainingQuantity, UnitCost)
WHERE IsExhausted = 0;
GO
```

### 2. T-SQL Stored Procedure (Cursor-less FIFO Allocation Engine)
```sql
CREATE OR ALTER PROCEDURE dbo.usp_Erp_ConsumeStockFifo
    @TenantId           UNIQUEIDENTIFIER,
    @ItemSku            NVARCHAR(50),
    @WarehouseId        INT,
    @QuantityToConsume  DECIMAL(18, 4),
    @ReferenceDocNumber NVARCHAR(50),
    @TotalCostAllocated DECIMAL(18, 4) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @QuantityToConsume <= 0
    BEGIN
        THROW 51001, 'Quantity to consume must be strictly positive.', 1;
        RETURN;
    END

    SET @TotalCostAllocated = 0.0000;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @BatchAllocations TABLE
        (
            BatchId             UNIQUEIDENTIFIER NOT NULL,
            AllocatedQuantity   DECIMAL(18, 4)   NOT NULL,
            UnitCost            DECIMAL(18, 4)   NOT NULL
        );

        ;WITH FifoCandidateBatches AS
        (
            SELECT 
                BatchId,
                RemainingQuantity,
                UnitCost,
                ReceivedDateUtc,
                SUM(RemainingQuantity) OVER (ORDER BY ReceivedDateUtc ASC, CreatedAtUtc ASC) AS RunningTotal
            FROM dbo.ErpInventoryBatches WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND ItemSku = @ItemSku
              AND WarehouseId = @WarehouseId
              AND IsExhausted = 0
        )
        INSERT INTO @BatchAllocations (BatchId, AllocatedQuantity, UnitCost)
        SELECT 
            BatchId,
            CASE 
                WHEN RunningTotal - RemainingQuantity + @QuantityToConsume <= RunningTotal 
                     AND RunningTotal - RemainingQuantity < @QuantityToConsume
                     THEN @QuantityToConsume - (RunningTotal - RemainingQuantity)
                WHEN RunningTotal <= @QuantityToConsume 
                     THEN RemainingQuantity
                ELSE 0
            END AS AllocatedQuantity,
            UnitCost
        FROM FifoCandidateBatches
        WHERE (RunningTotal - RemainingQuantity) < @QuantityToConsume;

        DECLARE @TotalAllocatedQty DECIMAL(18, 4);
        SELECT 
            @TotalAllocatedQty = ISNULL(SUM(AllocatedQuantity), 0),
            @TotalCostAllocated = ISNULL(SUM(AllocatedQuantity * UnitCost), 0)
        FROM @BatchAllocations;

        IF @TotalAllocatedQty < @QuantityToConsume
        BEGIN
            THROW 51002, 'Insufficient inventory available to satisfy FIFO consumption request.', 1;
        END

        UPDATE b
        SET 
            b.RemainingQuantity = b.RemainingQuantity - a.AllocatedQuantity,
            b.IsExhausted = CASE WHEN b.RemainingQuantity - a.AllocatedQuantity = 0 THEN 1 ELSE 0 END
        FROM dbo.ErpInventoryBatches b
        INNER JOIN @BatchAllocations a ON b.BatchId = a.BatchId;

        INSERT INTO dbo.ErpStockConsumptionLedger (TenantId, ItemSku, WarehouseId, QuantityConsumed, TotalCostAllocated, ReferenceDocNumber, ConsumedAtUtc)
        VALUES (@TenantId, @ItemSku, @WarehouseId, @QuantityToConsume, @TotalCostAllocated, @ReferenceDocNumber, SYSUTCDATETIME());

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### 3. C# .NET 10 Domain Service Implementation
```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseERP.Domain.Services;

public sealed record FifoConsumptionResult(
    string Sku,
    decimal QuantityConsumed,
    decimal TotalCostAllocated,
    decimal EffectiveUnitCost
);

public sealed class FifoInventoryService
{
    private readonly string _connectionString;

    public FifoInventoryService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<FifoConsumptionResult> ConsumeStockAsync(
        Guid tenantId,
        string sku,
        int warehouseId,
        decimal quantity,
        string referenceDocNumber,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Erp_ConsumeStockFifo", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@ItemSku", SqlDbType.NVarChar, 50) { Value = sku });
        command.Parameters.Add(new SqlParameter("@WarehouseId", SqlDbType.Int) { Value = warehouseId });
        command.Parameters.Add(new SqlParameter("@QuantityToConsume", SqlDbType.Decimal) { Precision = 18, Scale = 4, Value = quantity });
        command.Parameters.Add(new SqlParameter("@ReferenceDocNumber", SqlDbType.NVarChar, 50) { Value = referenceDocNumber });

        var totalCostParam = new SqlParameter("@TotalCostAllocated", SqlDbType.Decimal)
        {
            Direction = ParameterDirection.Output,
            Precision = 18,
            Scale = 4
        };
        command.Parameters.Add(totalCostParam);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        decimal totalCost = (decimal)totalCostParam.Value;
        decimal effectiveUnitCost = quantity > 0 ? totalCost / quantity : 0m;

        return new FifoConsumptionResult(sku, quantity, totalCost, effectiveUnitCost);
    }
}
```

