        RETURN -1;
    END

    DECLARE @TotalAvailable DECIMAL(18, 2) = 0.00;
    DECLARE @AllocatedLots TABLE (
        ComponentLotId      UNIQUEIDENTIFIER NOT NULL,
        AllocatedUnits DECIMAL(18, 2) NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @TotalAvailable = ISNULL(SUM(UnitsInReel), 0.00)
        FROM dbo.ComponentLots WITH (UPDLOCK, ROWLOCK)
        WHERE TenantId = @TenantId
          AND WarehouseId = @WarehouseId
          AND PartNumber = @PartNumber
          AND UnitsInReel > 0.00;

        IF @TotalAvailable < @RequiredQty
        BEGIN
            DECLARE @ErrMsg NVARCHAR(200) = CONCAT('Insufficient inventory. Available: ', @TotalAvailable, ', Requested: ', @RequiredQty);
            THROW 51002, @ErrMsg, 1;
            RETURN -2;
        END

        WITH AvailableLots AS
        (
            SELECT 
                ComponentLotId,
                UnitsInReel,
                SUM(UnitsInReel) OVER (
                    ORDER BY InspectionDate ASC, ComponentLotId ASC
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal
            FROM dbo.ComponentLots WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND WarehouseId = @WarehouseId
              AND PartNumber = @PartNumber
              AND UnitsInReel > 0.00
        ),
        AllocationCalc AS
        (
            SELECT 
                ComponentLotId,
                UnitsInReel,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= @RequiredQty THEN UnitsInReel
                    ELSE UnitsInReel - (RunningTotal - @RequiredQty)
                END AS QtyToAllocate
            FROM AvailableLots
            WHERE RunningTotal - UnitsInReel < @RequiredQty
        )
        INSERT INTO @AllocatedLots (ComponentLotId, AllocatedUnits)
        SELECT ComponentLotId, QtyToAllocate
        FROM AllocationCalc;

        UPDATE target
        SET target.UnitsInReel = target.UnitsInReel - alloc.AllocatedUnits
        FROM dbo.ComponentLots target
        INNER JOIN @AllocatedLots alloc ON target.ComponentLotId = alloc.ComponentLotId;

        SELECT @AllocatedQty = ISNULL(SUM(AllocatedUnits), 0.00) FROM @AllocatedLots;
        SET @RemainingQty = @TotalAvailable - @AllocatedQty;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

