namespace EnterpriseERP.Api.Endpoints;

public sealed record ApprovalResult(Guid PurchaseOrderId, string Status, DateTimeOffset ApprovedAtUtc);
public sealed record ApprovePoBody(Guid PurchaseOrderId, Guid ApprovedByUserId);

public static class PurchaseOrderApprovalEndpoints
{
    public static RouteGroupBuilder MapApprovalEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/erp/purchase-orders")
            .WithTags("ERP Purchase Order Approvals")
            .RequireAuthorization();

        group.MapPost("/{id:guid}/approve",
            async Task<Results<Ok<ApprovalResult>, NotFound, Conflict, BadRequest<ProblemDetails>>> (
                Guid id,
                ApprovePoBody body,
                IPurchaseOrderApprovalService service,
                ILogger<PurchaseOrderApprovalEndpoints> logger,
                CancellationToken ct) =>
            {
                logger.LogInformation(
                    "Approving PurchaseOrder {PurchaseOrderId} by {UserId}",
                    id, body.ApprovedByUserId);

                try
                {
                    var result = await service.ApproveAsync(id, body.ApprovedByUserId, ct);

                    return result is null
                        ? TypedResults.NotFound()
                        : TypedResults.Ok(result);
                }
                catch (SqlException ex) when (ex.Number == 54001)
                {
                    logger.LogWarning(ex, "Conflict on PO approval: SqlError {Number}", ex.Number);
                    return TypedResults.Conflict(new ProblemDetails
                    {
                        Title  = "State Conflict",
                        Detail = "The purchase order has been modified concurrently. Refresh and retry.",
                        Status = StatusCodes.Status409Conflict
                    });
                }
                catch (SqlException ex) when (ex.Number == 54002)
                {
                    logger.LogWarning(ex, "Validation failure on PO approval: SqlError {Number}", ex.Number);
                    return TypedResults.BadRequest(new ProblemDetails
                    {
                        Title  = "Business Rule Violation",
                        Detail = ex.Message,
                        Status = StatusCodes.Status400BadRequest
                    });
                }
            })
        // Register endpoint filters in pipeline order (outermost first)
        .AddEndpointFilter<TenantContextFilter>()
        .AddEndpointFilter<ApprovalRequestValidationFilter>()
        .WithName("ApprovePurchaseOrder")
        .Produces<ApprovalResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound)
        .ProducesProblem(StatusCodes.Status409Conflict)
        .ProducesValidationProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}

/// <summary>
/// Endpoint filter: reads X-Tenant-ID header and stores TenantId in HttpContext.Items.
/// Returns 400 ProblemDetails if the header is absent or not a valid GUID.
/// </summary>
public sealed class TenantContextFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context,
        EndpointFilterDelegate next)
    {
        if (!context.HttpContext.Request.Headers.TryGetValue("X-Tenant-ID", out var raw)
            || !Guid.TryParse(raw, out var tenantId))
        {
            return Results.Problem(
                title:      "Missing Tenant Context",
                detail:     "A valid 'X-Tenant-ID' GUID header is required for all enterprise API calls.",
                statusCode: StatusCodes.Status400BadRequest);
        }

        context.HttpContext.Items["TenantId"] = tenantId;
        return await next(context);
    }
}

/// <summary>
/// Endpoint filter: validates the route {id} matches the body PurchaseOrderId.
/// Prevents accidental cross-entity writes.
/// </summary>
public sealed class ApprovalRequestValidationFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context,
        EndpointFilterDelegate next)
    {
        // Arguments are positionally bound: 0=Guid id, 1=ApprovePoBody body, ...
        var routeId = context.GetArgument<Guid>(0);
        var body    = context.GetArgument<ApprovePoBody>(1);

        if (routeId != body.PurchaseOrderId)
        {
            return Results.Problem(
                title:      "Identifier Mismatch",
                detail:     $"Route id '{routeId}' does not match body PurchaseOrderId '{body.PurchaseOrderId}'.",
                statusCode: StatusCodes.Status400BadRequest);
        }

        return await next(context);
    }
}

public interface IPurchaseOrderApprovalService
{
    Task<ApprovalResult?> ApproveAsync(Guid orderId, Guid approvedByUserId, CancellationToken ct);
}
```

### Key Architectural Highlights:
- IEndpointFilter pipeline: Two filters registered with `.AddEndpointFilter<T>()` — `TenantContextFilter` (outermost) validates the X-Tenant-ID header; `ApprovalRequestValidationFilter` (inner) guards route/body id consistency. Filters execute in registration order.
- SqlException error-number routing: `catch (SqlException ex) when (ex.Number == 54001)` maps to 409 Conflict; `when (ex.Number == 54002)` maps to 400 BadRequest — both return RFC 7807 ProblemDetails.
- TypedResults union: `Results<Ok<ApprovalResult>, NotFound, Conflict, BadRequest<ProblemDetails>>` provides compile-time verified HTTP response contracts with no runtime type erasure.

