    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.BmsMilestones (MilestoneId, TenantId, DeliveryStatus, MilestoneBudget)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
