```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using Azure.Core;
using Azure.Identity;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace EnterprisePlatform.Infrastructure.Azure;

public interface ISqlConnectionFactory
{
    Task<SqlConnection> CreateOpenConnectionAsync(CancellationToken cancellationToken = default);
}

public sealed class AzureManagedIdentitySqlConnectionFactory : ISqlConnectionFactory
{
    private readonly string _connectionString;
    private readonly TokenCredential _credential;
    private static readonly string[] AzureSqlScopes = ["https://database.windows.net/.default"];

    public AzureManagedIdentitySqlConnectionFactory(IConfiguration configuration)
    {
        _connectionString = configuration.GetConnectionString("AzureSqlDatabase") 
            ?? throw new InvalidOperationException("Connection string 'AzureSqlDatabase' is missing.");

        // Automatically resolves Managed Identity in Azure App Service / Container Apps,
        // and falls back to Azure CLI / Visual Studio credential in local development
        _credential = new DefaultAzureCredential(new DefaultAzureCredentialOptions
        {
            ExcludeInteractiveBrowserCredential = true
        });
    }

    public async Task<SqlConnection> CreateOpenConnectionAsync(CancellationToken cancellationToken = default)
    {
        var connection = new SqlConnection(_connectionString);

        // If connection string does not contain password/user credentials, authenticate via Azure AD Token
        var builder = new SqlConnectionStringBuilder(_connectionString);
        if (string.IsNullOrEmpty(builder.UserID) && string.IsNullOrEmpty(builder.Password))
        {
            var tokenRequestContext = new TokenRequestContext(AzureSqlScopes);
            var token = await _credential.GetTokenAsync(tokenRequestContext, cancellationToken).ConfigureAwait(false);
            connection.AccessToken = token.Token;
        }

        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
        return connection;
    }
}

public static class AzureSqlServiceExtensions
{
    public static IServiceCollection AddAzureSqlInfrastructure(this IServiceCollection services)
    {
        services.AddSingleton<ISqlConnectionFactory, AzureManagedIdentitySqlConnectionFactory>();
        return services;
    }
}
