Here is the high-performance C# .NET 10 ADO.NET streaming implementation for IoT entity `GatewayTelemetry`:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.IoT.Infrastructure.Data;

public readonly record struct GatewayTelemetrySummary(
    Guid ReadingId,
    Guid TenantId,
    string QualityRating,
    decimal MetricValue,
    DateTimeOffset CreatedAtUtc
);

public sealed class GatewayTelemetryQueryRepository
{
    private readonly string _connectionString;

    public GatewayTelemetryQueryRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<GatewayTelemetrySummary> StreamByStatusAsync(
        Guid tenantId,
        string status,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                ReadingId,
                TenantId,
                QualityRating,
                MetricValue,
                CreatedAtUtc
            FROM dbo.IotGatewayReadings WITH (READPAST)
            WHERE TenantId = @TenantId
              AND QualityRating = @Status
            ORDER BY CreatedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Status", SqlDbType.NVarChar, 50) { Value = status });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordPk = reader.GetOrdinal("ReadingId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("QualityRating");
        int ordVal = reader.GetOrdinal("MetricValue");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new GatewayTelemetrySummary(
                ReadingId: reader.GetGuid(ordPk),
                TenantId: reader.GetGuid(ordTenant),
                QualityRating: reader.GetString(ordStatus),
                MetricValue: reader.GetDecimal(ordVal),
                CreatedAtUtc: reader.GetDateTime(ordCreated)
            );
        }
    }
}
```

### Key Architectural Highlights:
- SequentialAccess: Employs sequential streaming to eliminate client memory buffering.
- Ordinal Caching: Caches column ordinals outside the read loop for maximum throughput.
- Cancellation Propagation: Forwards the CancellationToken directly to all async ADO.NET calls.

