    public static async Task<Results<Created<TimesheetSubmissionResponse>, BadRequest<ProblemDetails>>> SubmitTimesheetHandlerAsync(
        SubmitTimesheetRequest request,
        ITimesheetCommandService timesheetService,
        HttpContext httpContext,
        ILoggerFactory loggerFactory,
