public sealed class TimesheetValidationFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var request = context.GetArgument<SubmitTimesheetRequest>(0);

        var errors = new Dictionary<string, string[]>();

        if (request.Lines == null || request.Lines.Count == 0)
        {
            errors.Add("Lines", ["At least one timesheet work line item is required."]);
        }
        else
        {
            decimal totalHours = 0;
            foreach (var line in request.Lines)
            {
                if (line.Hours <= 0 || line.Hours > 24)
                {
                    errors.Add($"Line_{line.TaskId}", ["Hours per entry must be between 0.25 and 24.0."]);
                }
                totalHours += line.Hours;
            }

            if (totalHours > 80)
            {
                errors.Add("TotalHours", ["Total weekly submitted hours cannot exceed 80 hours."]);
            }
        }

        if (errors.Count > 0)
        {
            return Results.ValidationProblem(errors);
        }

        return await next(context);
    }
}
