            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@ReferenceNumber", SqlDbType.NVarChar, 50) { Value = referenceNumber });

        var dt = new DataTable();
        dt.Columns.Add("AccountNumber", typeof(string));
        dt.Columns.Add("PostingDirection", typeof(string));
        dt.Columns.Add("CurrencyCode", typeof(string));
        dt.Columns.Add("FxRate", typeof(decimal));
