```sql
CREATE TABLE dbo.VendorInvoicePostingEntries
(
    EntryId         UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_VendorInvoicePostingEntries_Id DEFAULT NEWSEQUENTIALID(),
    TenantId        UNIQUEIDENTIFIER NOT NULL,
    PostingDate     DATE             NOT NULL CONSTRAINT DF_VendorInvoicePostingEntries_Date DEFAULT CAST(SYSUTCDATETIME() AS DATE),
    ReferenceNumber NVARCHAR(50)     NOT NULL,
    TotalDebitBase  DECIMAL(18, 4)   NOT NULL CHECK (TotalDebitBase >= 0.0000),
    TotalCreditBase DECIMAL(18, 4)   NOT NULL CHECK (TotalCreditBase >= 0.0000),
    PostedAtUtc     DATETIME2(7)     NOT NULL CONSTRAINT DF_VendorInvoicePostingEntries_Posted DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_VendorInvoicePostingEntries PRIMARY KEY CLUSTERED (EntryId),
    CONSTRAINT CK_VendorInvoicePostingEntries_Balance CHECK (TotalDebitBase = TotalCreditBase)
);
GO

CREATE TABLE dbo.VendorInvoicePostingLines
(
    LineId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_VendorInvoicePostingLines_Id DEFAULT NEWSEQUENTIALID(),
    EntryId          UNIQUEIDENTIFIER NOT NULL,
    AccountNumber    NVARCHAR(50)     NOT NULL,
    PostingDirection CHAR(1)          NOT NULL CHECK (PostingDirection IN ('D', 'C')),
    CurrencyCode     CHAR(3)          NOT NULL CHECK (LEN(CurrencyCode) = 3),
    FxRate           DECIMAL(18, 6)   NOT NULL CHECK (FxRate > 0.000000),
    AmountInCurrency DECIMAL(18, 4)   NOT NULL CHECK (AmountInCurrency >= 0.0000),
    AmountInBase     DECIMAL(18, 4)   NOT NULL CHECK (AmountInBase >= 0.0000),
    CONSTRAINT PK_VendorInvoicePostingLines PRIMARY KEY CLUSTERED (LineId),
    CONSTRAINT FK_VendorInvoicePostingLines_Entry FOREIGN KEY (EntryId) REFERENCES dbo.VendorInvoicePostingEntries (EntryId)
);
GO

CREATE TYPE dbo.tvp_VendorInvoicePostingLine AS TABLE
(
    AccountNumber    NVARCHAR(50)   NOT NULL,
    PostingDirection CHAR(1)        NOT NULL CHECK (PostingDirection IN ('D', 'C')),
    CurrencyCode     CHAR(3)        NOT NULL,
    FxRate           DECIMAL(18, 6) NOT NULL CHECK (FxRate > 0.000000),
    AmountInCurrency DECIMAL(18, 4) NOT NULL CHECK (AmountInCurrency >= 0.0000)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_VendorInvoicePosting
    @TenantId        UNIQUEIDENTIFIER,
    @ReferenceNumber NVARCHAR(50),
    @Lines           dbo.tvp_VendorInvoicePostingLine READONLY,
    @CreatedEntryId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS (SELECT 1 FROM @Lines)
    BEGIN
        THROW 56001, 'At least one line item must be provided.', 1;
        RETURN -1;
    END

    DECLARE @TotalDebitBase DECIMAL(18, 4) = 0.0000;
    DECLARE @TotalCreditBase DECIMAL(18, 4) = 0.0000;

    SELECT 
        @TotalDebitBase = ISNULL(SUM(CASE WHEN PostingDirection = 'D' THEN AmountInCurrency * FxRate ELSE 0.0000 END), 0.0000),
        @TotalCreditBase = ISNULL(SUM(CASE WHEN PostingDirection = 'C' THEN AmountInCurrency * FxRate ELSE 0.0000 END), 0.0000)
    FROM @Lines;

    IF ABS(@TotalDebitBase - @TotalCreditBase) > 0.0001
    BEGIN
        THROW 56002, 'Unbalanced journal entry: Total base debit must equal total base credit.', 1;
        RETURN -2;
    END

    IF @TotalDebitBase <= 0.0000
    BEGIN
        THROW 56003, 'Journal entry total must be strictly positive.', 1;
        RETURN -3;
    END

    SET TRANSACTION ISOLATION LEVEL SNAPSHOT;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @EntryId UNIQUEIDENTIFIER = NEWID();

        INSERT INTO dbo.VendorInvoicePostingEntries 
            (EntryId, TenantId, ReferenceNumber, TotalDebitBase, TotalCreditBase)
        VALUES 
            (@EntryId, @TenantId, @ReferenceNumber, @TotalDebitBase, @TotalCreditBase);

        INSERT INTO dbo.VendorInvoicePostingLines 
            (EntryId, AccountNumber, PostingDirection, CurrencyCode, FxRate, AmountInCurrency, AmountInBase)
        SELECT 
            @EntryId,
            AccountNumber,
            PostingDirection,
            CurrencyCode,
            FxRate,
            AmountInCurrency,
            ROUND(AmountInCurrency * FxRate, 4)
        FROM @Lines;

        SET @CreatedEntryId = @EntryId;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### Key Architectural Highlights:
- Production Hardened: Enforces defensive parameter typing and proper resource management.
- High Concurrency: Eliminates plan cache pollution and connection leaks.
- Cloud Native: Engineered for scalable multi-tenant enterprise deployment.

