(
    ProductId       UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ProductCatalog_Id DEFAULT NEWSEQUENTIALID(),
    TenantId        UNIQUEIDENTIFIER NOT NULL,
    Sku             NVARCHAR(50)     NOT NULL,
    Title           NVARCHAR(200)    NOT NULL,
    UnitPrice       DECIMAL(18, 2)   NOT NULL CHECK (UnitPrice >= 0.00),
    TotalStock      INT              NOT NULL CHECK (TotalStock >= 0),
    AllocatedStock  INT              NOT NULL CONSTRAINT DF_ProductCatalog_Allocated DEFAULT 0 CHECK (AllocatedStock >= 0),
    RowVer          ROWVERSION       NOT NULL,
    CONSTRAINT PK_ProductCatalog PRIMARY KEY CLUSTERED (ProductId),
    CONSTRAINT UQ_ProductCatalog_Sku UNIQUE (TenantId, Sku),
    CONSTRAINT CK_ProductCatalog_Oversell CHECK (AllocatedStock <= TotalStock)
);
GO

CREATE TABLE dbo.CartReservations
(
    ReservationId    UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_CartReservations_Id DEFAULT NEWSEQUENTIALID(),
    TenantId         UNIQUEIDENTIFIER NOT NULL,
    CartId           UNIQUEIDENTIFIER NOT NULL,
    ProductId        UNIQUEIDENTIFIER NOT NULL,
    ReservedQuantity INT              NOT NULL CHECK (ReservedQuantity > 0),
    ExpiresAtUtc     DATETIME2(7)     NOT NULL,
    Status           NVARCHAR(20)     NOT NULL CHECK (Status IN ('Active', 'CheckedOut', 'Expired', 'Cancelled')),
    CreatedAtUtc     DATETIME2(7)     NOT NULL CONSTRAINT DF_CartReservations_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_CartReservations PRIMARY KEY CLUSTERED (ReservationId),
    CONSTRAINT FK_CartReservations_Product FOREIGN KEY (ProductId) REFERENCES dbo.ProductCatalog (ProductId)
);
GO

CREATE NONCLUSTERED INDEX IX_CartReservations_ExpiryScan
ON dbo.CartReservations (Status, ExpiresAtUtc)
INCLUDE (ProductId, ReservedQuantity)
WHERE Status = 'Active';
GO

CREATE TYPE dbo.tvp_CartReservationItem AS TABLE
(
    ProductId        UNIQUEIDENTIFIER NOT NULL,
    Quantity         INT              NOT NULL CHECK (Quantity > 0)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Retail_ReserveFlashSaleStock
    @TenantId      UNIQUEIDENTIFIER,
    @CartId        UNIQUEIDENTIFIER,
    @Items         dbo.tvp_CartReservationItem READONLY,
    @TtlMinutes    INT = 15,
    @ReservationId UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ExpiresAt DATETIME2(7) = DATEADD(MINUTE, @TtlMinutes, SYSUTCDATETIME());
    SET @ReservationId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Step 1: Release any existing expired reservations to reclaim inventory
        UPDATE target
        SET target.AllocatedStock = target.AllocatedStock - r.ReservedQuantity
        FROM dbo.ProductCatalog target
        INNER JOIN (
            SELECT ProductId, SUM(ReservedQuantity) AS ReservedQuantity
            FROM dbo.CartReservations WITH (UPDLOCK, ROWLOCK)
            WHERE TenantId = @TenantId
              AND Status = 'Active'
              AND ExpiresAtUtc < SYSUTCDATETIME()
            GROUP BY ProductId
        ) r ON target.ProductId = r.ProductId;

        UPDATE dbo.CartReservations
        SET Status = 'Expired'
        WHERE TenantId = @TenantId
          AND Status = 'Active'
          AND ExpiresAtUtc < SYSUTCDATETIME();

        -- Step 2: Optimistically verify and lock sufficient unallocated stock
        DECLARE @UnavailableProducts INT = 0;

        SELECT @UnavailableProducts = COUNT(*)
        FROM @Items req
        INNER JOIN dbo.ProductCatalog p WITH (UPDLOCK, ROWLOCK) ON req.ProductId = p.ProductId
        WHERE p.TenantId = @TenantId
          AND (p.TotalStock - p.AllocatedStock) < req.Quantity;

        IF @UnavailableProducts > 0
        BEGIN
            THROW 56001, 'Insufficient flash-sale stock available for one or more requested items.', 1;
            RETURN -1;
        END

        -- Step 3: Increment allocated stock atomically
        UPDATE target
        SET target.AllocatedStock = target.AllocatedStock + req.Quantity
        FROM dbo.ProductCatalog target
        INNER JOIN @Items req ON target.ProductId = req.ProductId;

        -- Step 4: Record active reservations
        INSERT INTO dbo.CartReservations (ReservationId, TenantId, CartId, ProductId, ReservedQuantity, ExpiresAtUtc, Status)
        SELECT 
            @ReservationId,
            @TenantId,
            @CartId,
            ProductId,
            Quantity,
            @ExpiresAt,
            'Active'
        FROM @Items;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

