```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseRetail.Infrastructure.Data;

public sealed record CartItemReservationDto(Guid ProductId, int Quantity);

public sealed record StockReservationResult(
    Guid ReservationId,
    Guid CartId,
    DateTimeOffset ExpiresAtUtc
);

public sealed class FlashSaleReservationRepository
{
    private readonly string _connectionString;

    public FlashSaleReservationRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<StockReservationResult> ReserveStockAsync(
        Guid tenantId,
        Guid cartId,
        IReadOnlyList<CartItemReservationDto> items,
        int ttlMinutes,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (items.Count == 0)
        {
            throw new ArgumentException("Reservation item list cannot be empty.", nameof(items));
        }

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Retail_ReserveFlashSaleStock", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@CartId", SqlDbType.UniqueIdentifier) { Value = cartId });
        command.Parameters.Add(new SqlParameter("@TtlMinutes", SqlDbType.Int) { Value = ttlMinutes });

        var tvpParam = new SqlParameter("@Items", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_CartReservationItem",
            Value = BuildReservationDataTable(items)
        };
        command.Parameters.Add(tvpParam);

        var outputReservationId = new SqlParameter("@ReservationId", SqlDbType.UniqueIdentifier)
        {
            Direction = ParameterDirection.InputOutput,
            Value = DBNull.Value
        };
        command.Parameters.Add(outputReservationId);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        if (outputReservationId.Value is null || outputReservationId.Value is DBNull)
        {
            throw new InvalidOperationException("Failed to obtain reservation identifier from stock reservation procedure.");
        }

        var resId = (Guid)outputReservationId.Value;

        return new StockReservationResult(
            ReservationId: resId,
            CartId: cartId,
            ExpiresAtUtc: DateTimeOffset.UtcNow.AddMinutes(ttlMinutes)
        );
    }

    private static DataTable BuildReservationDataTable(IReadOnlyList<CartItemReservationDto> items)
    {
        var dt = new DataTable();
        dt.Columns.Add("ProductId", typeof(Guid));
        dt.Columns.Add("Quantity", typeof(int));

        foreach (var item in items)
        {
            dt.Rows.Add(item.ProductId, item.Quantity);
        }

        return dt;
    }
}
