using Microsoft.Data.SqlClient;
using EnterpriseRetail.Infrastructure.Data;

namespace EnterpriseRetail.Api;

public static class RetailEndpoints
{
    public static RouteGroupBuilder MapRetailEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/retail/flash-sale")
            .WithTags("Retail Stock Reservation")
            .RequireAuthorization();

        group.MapPost("/carts/{cartId:guid}/reserve", async Task<Results<Ok<StockReservationResult>, BadRequest<ProblemDetails>, Conflict<ProblemDetails>>> (
            Guid cartId,
            ReserveStockRequest request,
            FlashSaleReservationRepository repository,
            CancellationToken cancellationToken) =>
        {
            try
            {
                var result = await repository.ReserveStockAsync(
                    tenantId: request.TenantId,
                    cartId: cartId,
                    items: request.Items,
                    ttlMinutes: request.TtlMinutes <= 0 ? 15 : request.TtlMinutes,
                    cancellationToken: cancellationToken
                );

                return TypedResults.Ok(result);
            }
            catch (SqlException ex) when (ex.Number == 56001)
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Inventory Depleted",
                    Detail = ex.Message
                });
            }
            catch (SqlException ex) when (ex.Number == 1205)
            {
                return TypedResults.Conflict(new ProblemDetails
                {
                    Title = "Reservation Contention Conflict",
                    Detail = "Concurrent reservation conflict. Please re-attempt checkout."
                });
            }
        })
        .WithName("ReserveFlashSaleStock")
        .Produces<StockReservationResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest)
        .ProducesProblem(StatusCodes.Status409Conflict);

        return group;
    }
}

public sealed record ReserveStockRequest(
    Guid TenantId,
    IReadOnlyList<CartItemReservationDto> Items,
    int TtlMinutes = 15
);
