### 1. SQL Server T-SQL Database Tier (Schema, TVP & Atomic Posting Sproc)
```sql
-- User-Defined Table Type for Journal Line Items
IF TYPE_ID(N'dbo.tvp_GlJournalLineItem') IS NULL
BEGIN
    CREATE TYPE dbo.tvp_GlJournalLineItem AS TABLE
    (
        LineNumber       INT            NOT NULL PRIMARY KEY CLUSTERED,
        LedgerAccountNum NVARCHAR(50)   NOT NULL,
        PostingDirection NVARCHAR(1)    NOT NULL CHECK (PostingDirection IN ('D', 'C')),
        Amount           DECIMAL(18, 2) NOT NULL CHECK (Amount > 0)
    );
END
GO

CREATE TABLE dbo.GlJournalEntries
(
    EntryId          UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_GlJournalEntries_Id DEFAULT NEWSEQUENTIALID(),
    TenantId         UNIQUEIDENTIFIER NOT NULL,
    PostingStatus    NVARCHAR(50)     NOT NULL CHECK (PostingStatus IN ('Draft', 'Posted', 'Reversed')),
    TotalDebitAmount DECIMAL(18, 2)   NOT NULL CONSTRAINT DF_GlJournalEntries_DebitZero DEFAULT 0.00,
    CreatedByUserId  UNIQUEIDENTIFIER NOT NULL,
    CreatedAtUtc     DATETIME2(7)     NOT NULL CONSTRAINT DF_GlJournalEntries_Created DEFAULT SYSUTCDATETIME(),
    IsActive         BIT              NOT NULL CONSTRAINT DF_GlJournalEntries_Active DEFAULT 1,

    CONSTRAINT PK_GlJournalEntries PRIMARY KEY CLUSTERED (EntryId)
);
GO

CREATE NONCLUSTERED INDEX IX_GlJournalEntries_TenantStatus
ON dbo.GlJournalEntries (TenantId, PostingStatus)
INCLUDE (TotalDebitAmount, CreatedAtUtc)
WHERE IsActive = 1;
GO

CREATE TABLE dbo.GlJournalLines
(
    EntryId          UNIQUEIDENTIFIER NOT NULL,
    LineNumber       INT              NOT NULL,
    LedgerAccountNum NVARCHAR(50)     NOT NULL,
    PostingDirection NVARCHAR(1)      NOT NULL CHECK (PostingDirection IN ('D', 'C')),
    Amount           DECIMAL(18, 2)   NOT NULL,

    CONSTRAINT PK_GlJournalLines PRIMARY KEY CLUSTERED (EntryId, LineNumber),
    CONSTRAINT FK_GlJournalLines_Entries FOREIGN KEY (EntryId) REFERENCES dbo.GlJournalEntries (EntryId) ON DELETE CASCADE
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Erp_PostPurchaseOrderJournalEntry
    @TenantId         UNIQUEIDENTIFIER,
    @LineItems        dbo.tvp_GlJournalLineItem READONLY,
    @CreatedById      UNIQUEIDENTIFIER,
    @TotalDebitAmount DECIMAL(18, 2),
    @RecordId         UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF (@RecordId IS NULL)
        SET @RecordId = NEWID();

    IF (@TotalDebitAmount <= 0.00 OR @TotalDebitAmount IS NULL)
        THROW 51001, 'Total Debit amount must be strictly positive.', 1;

    DECLARE @DebitSum DECIMAL(18, 2) = 0.00;
    DECLARE @CreditSum DECIMAL(18, 2) = 0.00;

    SELECT 
        @DebitSum = ISNULL(SUM(CASE WHEN PostingDirection = 'D' THEN Amount ELSE 0 END), 0.00),
        @CreditSum = ISNULL(SUM(CASE WHEN PostingDirection = 'C' THEN Amount ELSE 0 END), 0.00)
    FROM @LineItems;

    IF (@DebitSum <> @CreditSum OR @DebitSum <> @TotalDebitAmount)
        THROW 51002, 'Double-entry balance violation: Total Debits must equal Total Credits.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.GlJournalEntries (EntryId, TenantId, PostingStatus, TotalDebitAmount, CreatedByUserId, CreatedAtUtc)
        VALUES (@RecordId, @TenantId, 'Posted', @TotalDebitAmount, @CreatedById, SYSUTCDATETIME());

        INSERT INTO dbo.GlJournalLines (EntryId, LineNumber, LedgerAccountNum, PostingDirection, Amount)
        SELECT 
            @RecordId,
            LineNumber,
            LedgerAccountNum,
            PostingDirection,
            Amount
        FROM @LineItems;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### 2. C# .NET 10 ADO.NET Data Access Tier (TVP Structured Mapping & IAsyncEnumerable Streaming)
```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseERP.Domain.Data;

public readonly record struct JournalSummaryDto(
    Guid EntryId, 
    Guid TenantId, 
    string PostingStatus, 
    decimal TotalDebitAmount,
    DateTimeOffset CreatedAtUtc
);

public sealed record JournalLineItem(
    int LineNumber,
    string LedgerAccountNum,
    string PostingDirection,
    decimal Amount
);

public sealed class PurchaseOrderGlRepository
{
    private readonly string _connectionString;

    public PurchaseOrderGlRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<JournalSummaryDto> StreamUnpostedJournalsAsync(
        Guid tenantId,
        decimal minimumDebitBalance,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                EntryId, 
                TenantId, 
                PostingStatus, 
                TotalDebitAmount,
                CreatedAtUtc
            FROM dbo.GlJournalEntries
            WHERE TenantId = @TenantId
              AND PostingStatus = 'Draft'
              AND TotalDebitAmount >= @MinBalance
            ORDER BY CreatedAtUtc DESC;";

        await using var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var cmd = new SqlCommand(sql, conn)
        {
            CommandTimeout = 45
        };

        cmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        cmd.Parameters.Add(new SqlParameter("@MinBalance", SqlDbType.Decimal) { Precision = 18, Scale = 2, Value = minimumDebitBalance });

        await using var reader = await cmd.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordPk = reader.GetOrdinal("EntryId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("PostingStatus");
        int ordVal = reader.GetOrdinal("TotalDebitAmount");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new JournalSummaryDto(
                EntryId: reader.GetGuid(ordPk),
                TenantId: reader.GetGuid(ordTenant),
                PostingStatus: reader.GetString(ordStatus),
                TotalDebitAmount: reader.GetDecimal(ordVal),
                CreatedAtUtc: reader.GetDateTimeOffset(ordCreated)
            );
        }
    }

    public async Task<Guid> PostJournalEntryAsync(
        Guid tenantId,
        IReadOnlyList<JournalLineItem> lines,
        decimal totalDebitValue,
        Guid createdById,
        CancellationToken cancellationToken = default)
    {
        if (lines is null || lines.Count == 0)
            throw new ArgumentException("At least one journal line item is required.", nameof(lines));

        await using var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var cmd = new SqlCommand("dbo.usp_Erp_PostPurchaseOrderJournalEntry", conn)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 45
        };

        var outputParam = new SqlParameter("@RecordId", SqlDbType.UniqueIdentifier)
        {
            Direction = ParameterDirection.Output
        };

        var tvpParam = new SqlParameter("@LineItems", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_GlJournalLineItem",
            Value = CreateLineItemDataTable(lines)
        };

        cmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        cmd.Parameters.Add(tvpParam);
        cmd.Parameters.Add(new SqlParameter("@CreatedById", SqlDbType.UniqueIdentifier) { Value = createdById });
        cmd.Parameters.Add(new SqlParameter("@TotalDebitAmount", SqlDbType.Decimal) { Precision = 18, Scale = 2, Value = totalDebitValue });
        cmd.Parameters.Add(outputParam);

        await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        return (Guid)outputParam.Value!;
    }

    private static DataTable CreateLineItemDataTable(IReadOnlyList<JournalLineItem> lines)
    {
        var dt = new DataTable();
        dt.Columns.Add("LineNumber", typeof(int));
        dt.Columns.Add("LedgerAccountNum", typeof(string));
        dt.Columns.Add("PostingDirection", typeof(string));
        dt.Columns.Add("Amount", typeof(decimal));

        foreach (var line in lines)
        {
            dt.Rows.Add(line.LineNumber, line.LedgerAccountNum, line.PostingDirection, line.Amount);
        }

        return dt;
    }
}
```

