```csharp
using System;
using System.Collections.Generic;
using System.Security.Claims;
using System.Threading;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Routing;
using EnterpriseERP.Domain.Data;

namespace EnterpriseERP.Api.Endpoints;

public sealed record PostGlRequest(IReadOnlyList<JournalLineItem> LineItems, decimal TotalDebitAmount);
public sealed record PostGlResponse(Guid EntryId, string Message);

public static class ErpApiExtensions
{
    public static RouteGroupBuilder MapErpPurchaseOrderApi(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/erp/purchase-orders")
            .WithTags("ERP Purchase Orders")
            .RequireAuthorization();

        group.MapPost("/{orderId:guid}/post-gl", async Task<Results<Ok<PostGlResponse>, BadRequest<ProblemDetails>, UnauthorizedHttpResult>> (
            Guid orderId,
            PostGlRequest req,
            PurchaseOrderGlRepository repo,
            ClaimsPrincipal user,
            CancellationToken cancellationToken) =>
        {
            var userIdClaim = user.FindFirstValue(ClaimTypes.NameIdentifier);
            if (!Guid.TryParse(userIdClaim, out var userId))
            {
                return TypedResults.Unauthorized();
            }

            var tenantIdClaim = user.FindFirstValue("TenantId");
            if (!Guid.TryParse(tenantIdClaim, out var tenantId))
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Missing Tenant Context",
                    Detail = "The TenantId claim is missing or malformed.",
                    Status = StatusCodes.Status400BadRequest
                });
            }

            if (req.LineItems is null || req.LineItems.Count == 0)
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Invalid Journal Payload",
                    Detail = "Journal posting requires at least one debit and one credit line.",
                    Status = StatusCodes.Status400BadRequest
                });
            }

            var entryId = await repo.PostJournalEntryAsync(
                tenantId: tenantId,
                lines: req.LineItems,
                totalDebitValue: req.TotalDebitAmount,
                createdById: userId,
                cancellationToken: cancellationToken
            );

            return TypedResults.Ok(new PostGlResponse(entryId, "Journal entry posted successfully to General Ledger."));
        })
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("PostPurchaseOrderGl")
        .WithSummary("Posts an approved Purchase Order to the General Ledger via Double-Entry TVP");

        return group;
    }
}

public sealed class TenantContextFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var httpContext = context.HttpContext;
        if (!httpContext.Request.Headers.TryGetValue("X-Tenant-ID", out var raw) || !Guid.TryParse(raw, out var tenantId))
        {
            return Results.Problem("A valid X-Tenant-ID header is required.", statusCode: StatusCodes.Status400BadRequest);
        }
        httpContext.Items["TenantId"] = tenantId;
        return await next(context);
    }
}
