Here is the complete C# .NET 10 `SqlException` error-number mapping pattern using exception filters:

```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseFintech.Infrastructure.Data;

// Domain exceptions — one per SQL Server custom error number
public sealed class DuplicateTransactionException : Exception
{
    public int SqlErrorNumber { get; }
    public DuplicateTransactionException(int num, string msg) : base(msg) => SqlErrorNumber = num;
}

public sealed class InsufficientFundsException : Exception
{
    public int SqlErrorNumber { get; }
    public InsufficientFundsException(int num, string msg) : base(msg) => SqlErrorNumber = num;
}

public sealed class AccountFrozenException : Exception
{
    public int SqlErrorNumber { get; }
    public AccountFrozenException(int num, string msg) : base(msg) => SqlErrorNumber = num;
}

public sealed class PaymentRepository
{
    private readonly string _connectionString;

    public PaymentRepository(string connectionString)
        => _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));

    public async Task PostPaymentAsync(Guid transactionId, decimal amount, CancellationToken ct)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(ct).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_PostPayment", connection)
        {
            CommandType    = CommandType.StoredProcedure,
            CommandTimeout = 30
        };
        command.Parameters.Add(new SqlParameter("@TransactionId", SqlDbType.UniqueIdentifier) { Value = transactionId });
        command.Parameters.Add(new SqlParameter("@Amount", SqlDbType.Decimal) { Precision = 18, Scale = 4, Value = amount });

        try
        {
            await command.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
        }
        // Exception filters using `when` — each catch only fires for its specific error number.
        // Never use a single catch + if/else: that catches ALL SqlExceptions and loses the stack.
        catch (SqlException ex) when (ex.Number == 53001)
        {
            throw new DuplicateTransactionException(ex.Number,
                $"Transaction {transactionId} is a duplicate. Original error: {ex.Message}");
        }
        catch (SqlException ex) when (ex.Number == 53002)
        {
            throw new InsufficientFundsException(ex.Number,
                $"Insufficient funds to post amount {amount:C}. Original error: {ex.Message}");
        }
        catch (SqlException ex) when (ex.Number == 53003)
        {
            throw new AccountFrozenException(ex.Number,
                $"Target account is frozen. Posting denied. Original error: {ex.Message}");
        }
        // All other SqlExceptions (deadlock 1205, timeout -2, network, etc.) propagate naturally
    }
}
```

### Key Architectural Highlights:
- **`catch (SqlException ex) when (ex.Number == NNNNN)`**: Exception filters using `when` are the correct pattern. Each `catch` block only activates for its specific `ex.Number`. This is superior to a single `catch (SqlException ex)` + `if/else` because: (1) the filter is evaluated without unwinding the stack, preserving the original call stack in debugging; (2) each branch is self-documenting; (3) unmatched exceptions propagate naturally without explicit re-throw.
- **Custom error numbers in the 53xxx range**: Stored procedures use `THROW 53001, 'message', 1` to raise domain-specific errors. The ADO.NET layer maps these numbers to typed domain exceptions, completely decoupling the database error vocabulary from the API surface.
- **Do NOT use a single catch + if/else**: A monolithic `catch (SqlException ex) { if (ex.Number == ...) throw new X(); }` catches all SqlExceptions — including deadlocks, timeouts, and network errors — and requires a final `throw;` which loses the original stack frame in some runtime configurations.

