Here is the complete production-grade T-SQL implementation:

```sql
CREATE TYPE dbo.tvp_JournalLineItem AS TABLE
(
    AccountId    UNIQUEIDENTIFIER NOT NULL,
    DebitAmount  DECIMAL(18, 4)   NOT NULL CHECK (DebitAmount  >= 0.0000),
    CreditAmount DECIMAL(18, 4)   NOT NULL CHECK (CreditAmount >= 0.0000),
    CurrencyCode CHAR(3)          NOT NULL,
    FxRate       DECIMAL(18, 6)   NOT NULL CHECK (FxRate > 0.000000)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_PostGeneralLedger
    @TenantId        UNIQUEIDENTIFIER,
    @ReferenceNumber NVARCHAR(50),
    @CreatedByUserId UNIQUEIDENTIFIER,
    @Lines           dbo.tvp_JournalLineItem READONLY,
    @EntryId         UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Validate TVP is non-empty before opening a transaction
    IF NOT EXISTS (SELECT 1 FROM @Lines)
    BEGIN
        THROW 54003, 'Journal entry cannot be empty: TVP contains no line items.', 1;
        RETURN -3;
    END

    -- Calculate double-entry balance before acquiring locks
    DECLARE @TotalDebit  DECIMAL(18, 4);
    DECLARE @TotalCredit DECIMAL(18, 4);

    SELECT
        @TotalDebit  = ISNULL(SUM(DebitAmount),  0.0000),
        @TotalCredit = ISNULL(SUM(CreditAmount), 0.0000)
    FROM @Lines;

    IF @TotalDebit <> @TotalCredit
    BEGIN
        THROW 54001, 'Double-entry invariant violation: SUM(DebitAmount) must equal SUM(CreditAmount).', 1;
        RETURN -1;
    END

    IF @TotalDebit = 0.0000
    BEGIN
        THROW 54002, 'Double-entry invariant violation: posting amounts cannot all be zero.', 1;
        RETURN -2;
    END

    SET @EntryId = NEWID();

    BEGIN TRY
        -- SNAPSHOT isolation must be SET before BEGIN TRANSACTION
        SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
        BEGIN TRANSACTION;

        INSERT INTO dbo.JournalEntries
            (EntryId, TenantId, ReferenceNumber, CreatedByUserId, PostedAtUtc)
        VALUES
            (@EntryId, @TenantId, @ReferenceNumber, @CreatedByUserId, SYSUTCDATETIME());

        INSERT INTO dbo.JournalEntryLines
            (EntryId, AccountId, DebitAmount, CreditAmount, CurrencyCode, FxRate, BaseDebit, BaseCredit)
        SELECT
            @EntryId,
            AccountId,
            DebitAmount,
            CreditAmount,
            CurrencyCode,
            FxRate,
            ROUND(DebitAmount  * FxRate, 4),
            ROUND(CreditAmount * FxRate, 4)
        FROM @Lines;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### Key Architectural Highlights:
- **SNAPSHOT Isolation Before BEGIN TRANSACTION**: `SET TRANSACTION ISOLATION LEVEL SNAPSHOT` must appear *before* `BEGIN TRANSACTION` — placing it inside the transaction has no effect. This eliminates reader-writer blocking on the JournalEntries table during high-concurrency posting.
- **Pre-Transaction Invariant Validation**: The double-entry balance check (`SUM(DebitAmount) = SUM(CreditAmount)`) runs against the TVP *before* acquiring any row locks, avoiding unnecessary lock escalation on invalid inputs.
- **Custom THROW Error Numbers (54001–54003)**: Domain-specific error numbers in the 54xxx range allow the ADO.NET and API layers to map `SqlException.Number` to typed `ProblemDetails` responses without string parsing.
- **`XACT_STATE() <> 0 ROLLBACK`**: The rollback guard uses `<> 0` (not `= 1`) to catch both committable (`1`) and uncommittable (`-1`) transaction states, ensuring no orphaned transactions escape the CATCH block.

Here is the complete implementation for Snapshot Isolation with Optimistic Concurrency in C# .NET 10 using ADO.NET Microsoft.Data.SqlClient:

```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterprisePlatform.Infrastructure.Transactions;

public sealed class CrmDealTransactionManager
{
    private readonly string _connectionString;

    public CrmDealTransactionManager(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Executes transaction under IsolationLevel.Snapshot to guarantee data consistency.
    /// Prevent write skew and phantom reads during concurrent CRM deal stage transitions without locking the table.
    /// </summary>
    public async Task<bool> ExecuteAtomicOperationAsync(
        Guid tenantId,
        Guid recordId,
        decimal dealamount,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Open transaction with explicit isolation level
        await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(
            IsolationLevel.Snapshot, 
            cancellationToken
        ).ConfigureAwait(false);

        try
        {
            const string updateSql = @"
                UPDATE dbo.CrmDeals WITH (ROWLOCK)
                SET DealAmount = DealAmount + @DeltaAmount,
                    LastModifiedUtc = SYSUTCDATETIME()
                WHERE TenantId = @TenantId
                  AND Id = @RecordId;";

            await using var cmd = new SqlCommand(updateSql, connection, transaction)
            {
                CommandTimeout = 30
            };

            cmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
            cmd.Parameters.Add(new SqlParameter("@RecordId", SqlDbType.UniqueIdentifier) { Value = recordId });

            var paramAmt = new SqlParameter("@DeltaAmount", SqlDbType.Decimal)
            {
                Precision = 18,
                Scale = 2,
                Value = dealamount
            };
            cmd.Parameters.Add(paramAmt);

            int rowsAffected = await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

            if (rowsAffected == 0)
            {
                await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
                return false;
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return true;
        }
        catch (SqlException ex) when (ex.Number == 1205) // Deadlock victim
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw new InvalidOperationException("Transaction was chosen as deadlock victim. Retry policy should trigger.", ex);
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }
}
```

### Key Architectural Highlights:
- Isolation Semantics: Enforces IsolationLevel.Snapshot to guarantee data consistency.
- Deadlock Handling: Catches SqlException 1205 (deadlock victim) with clean transaction rollback and retry compatibility.
- Atomic State Modification: Updates entity state and metadata timestamps within a dedicated transaction.

