using Microsoft.AspNetCore.Routing;

namespace Enterprise.CRM.Api.Endpoints;

public sealed record CustomerLeadDto(Guid LeadId, Guid TenantId, string LeadStage, decimal EstimatedDealValue);

public static class CustomerLeadEndpointExtensions
{
    public static RouteGroupBuilder MapCustomerLeadEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/crm/customerleads")
            .WithTags("CRM - CustomerLead")
            .RequireAuthorization();

        group.MapGet("/{id:guid}", async Task<Results<Ok<CustomerLeadDto>, NotFound<ProblemDetails>, UnauthorizedHttpResult>> (
            Guid id,
            ClaimsPrincipal user,
            CancellationToken ct) =>
        {
            var tenantClaim = user.FindFirstValue("TenantId");
            if (!Guid.TryParse(tenantClaim, out var tenantId))
            {
                return TypedResults.Unauthorized();
            }

            var item = new CustomerLeadDto(id, tenantId, "Won", 1500.00m);
            return TypedResults.Ok(item);
        })
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("GetCustomerLeadById")
        .Produces<CustomerLeadDto>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound);

        return group;
    }
}

public sealed class TenantContextFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var httpContext = context.HttpContext;
