{
    public static RouteGroupBuilder MapFxHedgingContractEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/fintech/fxhedgingcontracts")
            .WithTags("Fintech - FxHedgingContract")
            .RequireAuthorization();

        group.MapGet("/{id:guid}", async Task<Results<Ok<FxHedgingContractDto>, NotFound<ProblemDetails>, UnauthorizedHttpResult>> (
