        .AddEndpointFilter<TenantContextFilter>()
        .WithName("GetFxHedgingContractById")
        .Produces<FxHedgingContractDto>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound);

        return group;
    }
}

