Here is the complete production-grade C# .NET 10 implementation:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseFintech.Infrastructure.Data;

public readonly record struct RevaluatedPosition(
    Guid   PositionId,
    string InstrumentCode,
    string CurrencyCode,
    decimal OriginalAmount,
    decimal RevaluedBaseAmount,
    DateTimeOffset ValuationUtc
);

// Domain exceptions mapped from SqlException error numbers
public sealed class InvariantViolationException : Exception
{
    public int SqlErrorNumber { get; }
    public InvariantViolationException(int number, string message) : base(message)
        => SqlErrorNumber = number;
}

public sealed class StaleRateException : Exception
{
    public int SqlErrorNumber { get; }
    public StaleRateException(int number, string message) : base(message)
        => SqlErrorNumber = number;
}

public sealed class FxRevaluationService
{
    private readonly string _connectionString;

    public FxRevaluationService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Streams revalued forex positions asynchronously using SequentialAccess.
    /// Maps SqlException error numbers to typed domain exceptions.
    /// </summary>
    public async IAsyncEnumerable<RevaluatedPosition> StreamRevaluatedPositionsAsync(
        string baseCurrency,
        [EnumeratorCancellation] CancellationToken ct)
    {
        const string sql = @"
            SELECT
                p.PositionId,
                p.InstrumentCode,
                p.CurrencyCode,
                p.OriginalAmount,
                ROUND(p.OriginalAmount * r.FxRate, 4) AS RevaluedBaseAmount,
                r.RateTimestampUtc                     AS ValuationUtc
            FROM dbo.FxPositions   p WITH (NOLOCK)
            INNER JOIN dbo.FxRates r WITH (NOLOCK)
                ON r.FromCurrency = p.CurrencyCode
               AND r.ToCurrency   = @BaseCurrency
               AND r.IsActive     = 1
            ORDER BY p.InstrumentCode ASC;";

        await using var connection = new SqlConnection(_connectionString);

        try
        {
            await connection.OpenAsync(ct).ConfigureAwait(false);
        }
        catch (SqlException ex) when (ex.Number == 54001)
        {
            throw new InvariantViolationException(ex.Number,
                $"Ledger invariant violation opening revaluation connection: {ex.Message}");
        }

        await using var command = new SqlCommand(sql, connection)
        {
            CommandType    = CommandType.Text,
            CommandTimeout = 30
        };
        command.Parameters.Add(new SqlParameter("@BaseCurrency", SqlDbType.NChar, 3) { Value = baseCurrency });

        SqlDataReader reader;
        try
        {
            reader = await command.ExecuteReaderAsync(
                CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
                ct).ConfigureAwait(false);
        }
        catch (SqlException ex) when (ex.Number == 54002)
        {
            throw new StaleRateException(ex.Number,
                $"FX rate data is stale or missing for base currency '{baseCurrency}': {ex.Message}");
        }
        catch (SqlException ex) when (ex.Number == 54001)
        {
            throw new InvariantViolationException(ex.Number,
                $"Revaluation query invariant failure: {ex.Message}");
        }

        await using (reader)
        {
            int ordPositionId    = reader.GetOrdinal("PositionId");
            int ordInstrument    = reader.GetOrdinal("InstrumentCode");
            int ordCurrency      = reader.GetOrdinal("CurrencyCode");
            int ordOriginal      = reader.GetOrdinal("OriginalAmount");
            int ordRevalued      = reader.GetOrdinal("RevaluedBaseAmount");
            int ordValuation     = reader.GetOrdinal("ValuationUtc");

            while (await reader.ReadAsync(ct).ConfigureAwait(false))
            {
                var positionId   = await reader.GetFieldValueAsync<Guid>           (ordPositionId, ct).ConfigureAwait(false);
                var instrument   = await reader.GetFieldValueAsync<string>         (ordInstrument, ct).ConfigureAwait(false);
                var currency     = await reader.GetFieldValueAsync<string>         (ordCurrency,   ct).ConfigureAwait(false);
                var original     = await reader.GetFieldValueAsync<decimal>        (ordOriginal,   ct).ConfigureAwait(false);
                var revalued     = await reader.GetFieldValueAsync<decimal>        (ordRevalued,   ct).ConfigureAwait(false);
                var valuation    = await reader.GetFieldValueAsync<DateTimeOffset>  (ordValuation,  ct).ConfigureAwait(false);

                yield return new RevaluatedPosition(positionId, instrument, currency, original, revalued, valuation);
            }
        }
    }
}
```

### Key Architectural Highlights:
- **SqlException Error-Number Mapping**: `catch (SqlException ex) when (ex.Number == 54001)` and `when (ex.Number == 54002)` translate raw database error codes into typed domain exceptions (`InvariantViolationException`, `StaleRateException`). This decouples the API layer from raw SqlException numbers.
- **`[EnumeratorCancellation]` attribute**: Applied to the `CancellationToken ct` parameter so the compiler generates correct cancellation propagation into the iterator state machine. Without this attribute, cancellation tokens passed via `WithCancellation()` are silently ignored.
- **`CommandBehavior.SequentialAccess`**: Prevents the driver from buffering all column data in memory. Combined with `GetFieldValueAsync<T>(ordinal, ct)`, each column is read directly from the network stream in ordinal order.
- **`GetFieldValueAsync<T>(ordinal, ct)` — 2-argument form**: The correct ADO.NET API. Do NOT pass buffer, offset, or length arguments — those belong to `GetBytesAsync` for LOB columns.

