### 1. SQL Server T-SQL Schema & Sproc (`dbo.AchTransferBatches`)
```sql
CREATE TABLE dbo.AchTransferBatches
(
    BatchId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_AchTransferBatches_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    SettlementStatus   NVARCHAR(50)     NOT NULL,
    TotalSettlementAmount      DECIMAL(18, 2)   NOT NULL,
    CreatedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_AchTransferBatches_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_AchTransferBatches PRIMARY KEY CLUSTERED (BatchId)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Fintech_CreateACHTransferBatch
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.AchTransferBatches (BatchId, TenantId, SettlementStatus, TotalSettlementAmount)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
