    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.AchTransferBatches (BatchId, TenantId, SettlementStatus, TotalSettlementAmount)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
