Here is the complete C# .NET 10 three-layer SqlException mapping pattern:

```csharp
using System;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Routing;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Logging;

namespace EnterpriseFintech;

// ============================================================================
// 1. DOMAIN EXCEPTION — mapped from SqlException error number 54001
// ============================================================================
public sealed class LedgerBalanceException : Exception
{
    public int SqlErrorNumber { get; }
    public LedgerBalanceException(int num, string msg) : base(msg) => SqlErrorNumber = num;
}

// ============================================================================
// 2. REPOSITORY LAYER — catches SqlException, throws LedgerBalanceException
// ============================================================================
public sealed class LedgerRepository
{
    private readonly string _connectionString;

    public LedgerRepository(string cs) => _connectionString = cs;

    public async Task PostEntryAsync(Guid entryId, decimal amount, CancellationToken ct)
    {
        await using var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync(ct).ConfigureAwait(false);

        await using var cmd = new SqlCommand("dbo.usp_PostLedgerEntry", conn)
        {
            CommandType    = CommandType.StoredProcedure,
            CommandTimeout = 30
        };
        cmd.Parameters.Add(new SqlParameter("@EntryId", SqlDbType.UniqueIdentifier) { Value = entryId });
        cmd.Parameters.Add(new SqlParameter("@Amount",  SqlDbType.Decimal) { Precision = 18, Scale = 4, Value = amount });

        try
        {
            await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
        }
        // SqlException 54001 → domain exception at the repository boundary
        catch (SqlException ex) when (ex.Number == 54001)
        {
            throw new LedgerBalanceException(ex.Number,
                $"Ledger double-entry invariant violated for entry {entryId}: {ex.Message}");
        }
        // All other SqlExceptions (deadlock 1205, timeout -2) propagate naturally
    }
}

// ============================================================================
// 3. DOMAIN SERVICE LAYER — no catch; LedgerBalanceException propagates up
// ============================================================================
public sealed class LedgerService
{
    private readonly LedgerRepository _repo;
    public LedgerService(LedgerRepository repo) => _repo = repo;

    public Task PostEntryAsync(Guid entryId, decimal amount, CancellationToken ct)
        => _repo.PostEntryAsync(entryId, amount, ct);
}

// ============================================================================
// 4. API LAYER — catches LedgerBalanceException, returns TypedResults.Conflict
// ============================================================================
public sealed record PostLedgerRequest(Guid EntryId, decimal Amount);
public sealed record PostLedgerResponse(Guid EntryId, string Status);

public static class LedgerEndpoints
{
    public static RouteGroupBuilder MapLedgerEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/fintech/ledger")
            .WithTags("Fintech Ledger")
            .RequireAuthorization();

        group.MapPost("/entries",
            async Task<Results<Created<PostLedgerResponse>, Conflict<ProblemDetails>>> (
                PostLedgerRequest req,
                LedgerService service,
                ILogger<LedgerEndpoints> logger,
                CancellationToken ct) =>
            {
                try
                {
                    await service.PostEntryAsync(req.EntryId, req.Amount, ct);

                    logger.LogInformation("Ledger entry {EntryId} posted successfully", req.EntryId);
                    return TypedResults.Created(
                        $"/api/fintech/ledger/entries/{req.EntryId}",
                        new PostLedgerResponse(req.EntryId, "Posted"));
                }
                // LedgerBalanceException surfaces from repository via SqlException 54001 mapping
                catch (LedgerBalanceException ex)
                {
                    logger.LogWarning(ex, "Ledger balance conflict on entry {EntryId}, SqlError {Num}",
                        req.EntryId, ex.SqlErrorNumber);
                    return TypedResults.Conflict(new ProblemDetails
                    {
                        Title  = "Ledger Balance Conflict",
                        Detail = ex.Message,
                        Status = StatusCodes.Status409Conflict
                    });
                }
            })
        .WithName("PostLedgerEntry")
        .Produces<PostLedgerResponse>(StatusCodes.Status201Created)
        .ProducesProblem(StatusCodes.Status409Conflict);

        return group;
    }
}
```

### Key Architectural Highlights:
- **Repository boundary mapping**: `catch (SqlException ex) when (ex.Number == 54001)` at the repository layer translates the raw database error into a typed domain exception. The API layer never sees `SqlException` directly — it catches `LedgerBalanceException`, which is a pure domain type with no database dependency.
- **`TypedResults.Conflict(new ProblemDetails {...})`**: The Minimal API endpoint returns `Results<Created<PostLedgerResponse>, Conflict<ProblemDetails>>` — a compile-time verified union. `TypedResults.Conflict(pd)` maps to HTTP 409 with an RFC 7807 body.
- **Service layer transparency**: `LedgerService.PostEntryAsync` does not catch — it lets `LedgerBalanceException` propagate naturally. This keeps domain services free of cross-cutting concerns.

