CREATE OR ALTER PROCEDURE dbo.usp_MES_CreateWorkOrder
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
