                        <option value="Empty">Empty</option><option value="Partial">Partial</option><option value="Full">Full</option><option value="Reserved">Reserved</option>
                    </select>
                </div>
                <div class="col-md-2">
                    <button class="btn btn-outline-secondary w-100" id="btnFilter">
                        <i class="bi bi-funnel me-1"></i> Filter
                    </button>
                </div>
            </div>
        </div>

        <!-- Records Table -->
        <div class="app-card p-4">
            <div class="table-responsive">
                <table class="table table-hover align-middle mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Identifier</th>
                            <th>Description</th>
                            <th>Status</th>
                            <th>Amount / Value</th>
                            <th>Last Updated</th>
                            <th class="text-end">Actions</th>
