    <script>
        class BinController {
            constructor() {
                this.tbody = document.getElementById('tableBody');
                this.filterKeyword = document.getElementById('filterKeyword');
                this.filterStatus = document.getElementById('filterStatus');
                this.form = document.getElementById('createForm');
                this.items = [];
                this.init();
            }

            async init() {
                document.getElementById('btnFilter').addEventListener('click', () => this.applyFilter());
                this.form.addEventListener('submit', (e) => this.handleSubmit(e));
                await this.fetchData();
            }

            async fetchData() {
                try {
                    const res = await fetch('/api/v1/erp/bins');
                    this.items = res.ok ? await res.json() : [];
                    this.render(this.items);
                } catch {
                    this.tbody.innerHTML = '<tr><td colspan="6" class="text-center py-4 text-danger">Failed to load data.</td></tr>';
                }
            }

            render(records) {
                if (!records.length) {
                    this.tbody.innerHTML = '<tr><td colspan="6" class="text-center py-4 text-muted">No records found.</td></tr>';
                    return;
                }
                this.tbody.innerHTML = records.map(r => `
                    <tr>
                        <td class="fw-semibold text-primary">#${r.id.substring(0,8)}</td>
                        <td>${r.name}</td>
                        <td><span class="badge bg-secondary">${r.status}</span></td>
                        <td>${new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(r.amount || 0)}</td>
                        <td>${new Date(r.createdAtUtc).toLocaleDateString()}</td>
                        <td class="text-end">
                            <button class="btn btn-sm btn-outline-primary" onclick="controller.edit('${r.id}')">Edit</button>
                        </td>
                    </tr>
                `).join('');
            }

            applyFilter() {
                const kw = this.filterKeyword.value.toLowerCase();
                const st = this.filterStatus.value;
                const filtered = this.items.filter(i => 
                    (!kw || i.name.toLowerCase().includes(kw)) &&
                    (!st || i.status === st)
                );
                this.render(filtered);
            }

            async handleSubmit(e) {
                e.preventDefault();
                const payload = {
                    name: document.getElementById('inputName').value,
                    status: document.getElementById('inputStatus').value
                };
                await fetch('/api/v1/erp/bins', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                bootstrap.Modal.getInstance(document.getElementById('createModal')).hide();
                await this.fetchData();
            }

            edit(id) { console.log('Editing', id); }
        }

        const controller = new BinController();
    </script>
</body>
</html>
```

### Key Architectural Highlights:
- Dynamic Filtering: Dynamically filters `Bin` records in-memory by search keywords and status.
- Async API Integration: Loads and submits records to ASP.NET .NET 10 endpoints using asynchronous Fetch.
- Zero-Framework UI: Eliminates heavy framework overhead with clean ES6+ classes and Bootstrap 5 components.

Here is the high-performance C# .NET 10 ADO.NET streaming implementation for ERP entity `JournalEntry`:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.ERP.Infrastructure.Data;

public readonly record struct JournalEntrySummary(
    Guid EntryId,
    Guid TenantId,
    string PostingStatus,
    decimal TotalDebitAmount,
    DateTimeOffset CreatedAtUtc
);

public sealed class JournalEntryQueryRepository
{
    private readonly string _connectionString;

    public JournalEntryQueryRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async IAsyncEnumerable<JournalEntrySummary> StreamByStatusAsync(
        Guid tenantId,
        string status,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                EntryId,
                TenantId,
                PostingStatus,
                TotalDebitAmount,
                CreatedAtUtc
            FROM dbo.GlJournalEntries WITH (READPAST)
            WHERE TenantId = @TenantId
              AND PostingStatus = @Status
            ORDER BY CreatedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Status", SqlDbType.NVarChar, 50) { Value = status });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordPk = reader.GetOrdinal("EntryId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("PostingStatus");
        int ordVal = reader.GetOrdinal("TotalDebitAmount");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new JournalEntrySummary(
                EntryId: reader.GetGuid(ordPk),
                TenantId: reader.GetGuid(ordTenant),
                PostingStatus: reader.GetString(ordStatus),
                TotalDebitAmount: reader.GetDecimal(ordVal),
                CreatedAtUtc: reader.GetDateTime(ordCreated)
            );
        }
    }
}
```

### Key Architectural Highlights:
- SequentialAccess: Employs sequential streaming to eliminate client memory buffering.
- Ordinal Caching: Caches column ordinals outside the read loop for maximum throughput.
- Cancellation Propagation: Forwards the CancellationToken directly to all async ADO.NET calls.

