CREATE TABLE dbo.CrmOpportunities
(
    OpportunityId           UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_CrmOpportunities_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    StageName   NVARCHAR(50)     NOT NULL,
