    CreatedAtUtc   DATETIME2(7)     NOT NULL CONSTRAINT DF_CrmOpportunities_Created DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_CrmOpportunities PRIMARY KEY CLUSTERED (OpportunityId)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_CRM_CreateSalesOpportunity
    @TenantId   UNIQUEIDENTIFIER,
    @Status     NVARCHAR(50),
    @Value      DECIMAL(18, 2),
    @CreatedId  UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @CreatedId = NEWID();

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.CrmOpportunities (OpportunityId, TenantId, StageName, ForecastAmount)
        VALUES (@CreatedId, @TenantId, @Status, @Value);

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

