namespace Enterprise.BMS.Api.Endpoints;

public sealed record ProjectBudgetLineDto(Guid BudgetLineId, Guid TenantId, string VarianceStatus, decimal AllocatedCost);

public static class ProjectBudgetLineEndpointExtensions
{
    public static RouteGroupBuilder MapProjectBudgetLineEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/bms/projectbudgetlines")
            .WithTags("BMS - ProjectBudgetLine")
            .RequireAuthorization();

        group.MapGet("/{id:guid}", async Task<Results<Ok<ProjectBudgetLineDto>, NotFound<ProblemDetails>, UnauthorizedHttpResult>> (
            Guid id,
            ClaimsPrincipal user,
            CancellationToken ct) =>
        {
            var tenantClaim = user.FindFirstValue("TenantId");
            if (!Guid.TryParse(tenantClaim, out var tenantId))
            {
