using System;
using System.Security.Claims;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace EnterpriseERP.Api.Endpoints;

public sealed record ApprovePoRequest(
    Guid OrderId,
    decimal ApprovedAmount,
    string ApprovalComments
);

public sealed record PurchaseOrderResponse(
    Guid OrderId,
    string OrderNumber,
    string Status,
    decimal TotalAmount,
    DateTimeOffset ApprovedAtUtc,
    string ApprovedBy
);

public interface IPurchaseOrderService
{
    Task<PurchaseOrderResponse?> ApprovePurchaseOrderAsync(
        Guid orderId, 
        decimal approvedAmount, 
        string comments, 
        Guid approverUserId, 
        CancellationToken cancellationToken);
}

public static class PurchaseOrderEndpoints
{
    public static RouteGroupBuilder MapPurchaseOrderEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/erp/purchase-orders")
            .WithTags("ERP Purchase Orders")
            .RequireAuthorization("RequireFinancialApproverRole");

        group.MapPost("/{id:guid}/approve", ApproveOrderAsync)
            .WithName("ApprovePurchaseOrder")
            .WithSummary("Approves an ERP Purchase Order with financial authority check")
            .AddEndpointFilter<TenantContextEndpointFilter>()
            .AddEndpointFilter<ValidationFilter<ApprovePoRequest>>()
            .Produces<PurchaseOrderResponse>(StatusCodes.Status200OK)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesValidationProblem(StatusCodes.Status400BadRequest);

        return group;
    }

    public static async Task<Results<Ok<PurchaseOrderResponse>, NotFound<ProblemDetails>, BadRequest<ProblemDetails>>> ApproveOrderAsync(
        Guid id,
        ApprovePoRequest request,
        IPurchaseOrderService poService,
        ClaimsPrincipal user,
        ILogger<PurchaseOrderEndpoints> logger,
        CancellationToken cancellationToken)
    {
        if (id != request.OrderId)
        {
            return TypedResults.BadRequest(new ProblemDetails
            {
                Title = "Mismatched Identifier",
                Detail = "The Route ID does not match the request payload OrderId.",
                Status = StatusCodes.Status400BadRequest
            });
        }

        var userIdClaim = user.FindFirstValue(ClaimTypes.NameIdentifier);
        if (!Guid.TryParse(userIdClaim, out var approverUserId))
        {
            return TypedResults.BadRequest(new ProblemDetails
            {
                Title = "Invalid Security Principal",
                Detail = "Authenticated user context does not contain a valid User Guid.",
                Status = StatusCodes.Status400BadRequest
            });
        }

        logger.LogInformation("Processing PO approval for OrderId: {OrderId} by User: {UserId}", id, approverUserId);

        var result = await poService.ApprovePurchaseOrderAsync(
            request.OrderId,
            request.ApprovedAmount,
            request.ApprovalComments,
            approverUserId,
            cancellationToken
        );

        if (result is null)
        {
            return TypedResults.NotFound(new ProblemDetails
            {
                Title = "Purchase Order Not Found",
                Detail = $"No active pending purchase order exists with ID '{id}'.",
                Status = StatusCodes.Status404NotFound
            });
        }

        return TypedResults.Ok(result);
    }
}

public sealed class TenantContextEndpointFilter : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var httpContext = context.HttpContext;
        if (!httpContext.Request.Headers.TryGetValue("X-Tenant-ID", out var tenantHeader) ||
            !Guid.TryParse(tenantHeader, out var tenantId))
        {
            return Results.Problem(
                title: "Missing Tenant Context",
                detail: "Enterprise API requests require a valid 'X-Tenant-ID' HTTP header.",
                statusCode: StatusCodes.Status400BadRequest
            );
        }

        httpContext.Items["TenantId"] = tenantId;
        return await next(context);
    }
}
