using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.IoTPlatform.Infrastructure.BulkIngestion;

public readonly record struct TelemetryEvent(
    Guid EventId,
    Guid TenantId,
    string DeviceCode,
    decimal SensorReading,
    DateTimeOffset ReceivedAtUtc
);

/// <summary>
/// Custom DbDataReader subclass wrapping IAsyncEnumerable<TelemetryEvent>.
/// SqlBulkCopy calls Read() in its internal pump — bridge async via GetAwaiter().GetResult().
/// </summary>
public sealed class TelemetryEventReader : DbDataReader
{
    private readonly IAsyncEnumerator<TelemetryEvent> _enumerator;
    private TelemetryEvent _current;
    private bool _isClosed;

    public TelemetryEventReader(IAsyncEnumerable<TelemetryEvent> source, CancellationToken ct)
    {
        _enumerator = source.GetAsyncEnumerator(ct);
    }

    // SqlBulkCopy calls Read() synchronously on a thread-pool thread
    public override bool Read()
    {
        var moved = _enumerator.MoveNextAsync().AsTask().GetAwaiter().GetResult();
        if (moved) _current = _enumerator.Current;
        return moved;
    }

    public override int FieldCount => 5;

    public override object GetValue(int ordinal) => ordinal switch
    {
        0 => _current.EventId,
        1 => _current.TenantId,
        2 => _current.DeviceCode,
        3 => _current.SensorReading,
        4 => _current.ReceivedAtUtc,
        _ => throw new IndexOutOfRangeException($"Ordinal {ordinal} out of range.")
    };

    public override string GetName(int ordinal) => ordinal switch
    {
        0 => "EventId",
        1 => "TenantId",
        2 => "DeviceCode",
        3 => "SensorReading",
        4 => "ReceivedAtUtc",
        _ => throw new IndexOutOfRangeException()
    };

    public override int GetOrdinal(string name) => name switch
    {
        "EventId"       => 0,
        "TenantId"      => 1,
        "DeviceCode"    => 2,
        "SensorReading" => 3,
        "ReceivedAtUtc" => 4,
        _               => throw new IndexOutOfRangeException($"Column '{name}' not found.")
    };

    public override Type GetFieldType(int ordinal) => ordinal switch
    {
        0 => typeof(Guid),
        1 => typeof(Guid),
        2 => typeof(string),
        3 => typeof(decimal),
        4 => typeof(DateTimeOffset),
        _ => throw new IndexOutOfRangeException()
    };

    public override bool IsDBNull(int ordinal)    => false;
    public override bool HasRows                  => true;
    public override bool IsClosed                 => _isClosed;
    public override int  RecordsAffected          => -1;
    public override int  Depth                    => 0;
    public override bool NextResult()             => false;

    public override void Close()
    {
        _isClosed = true;
        _enumerator.DisposeAsync().AsTask().GetAwaiter().GetResult();
    }

    public override Guid    GetGuid(int o)    => (Guid)GetValue(o);
    public override string  GetString(int o)  => (string)GetValue(o);
    public override decimal GetDecimal(int o) => (decimal)GetValue(o);
    public override DateTime GetDateTime(int o) => ((DateTimeOffset)GetValue(o)).UtcDateTime;
    public override bool    GetBoolean(int o) => (bool)GetValue(o);
    public override byte    GetByte(int o)    => (byte)GetValue(o);
    public override short   GetInt16(int o)   => (short)GetValue(o);
    public override int     GetInt32(int o)   => (int)GetValue(o);
    public override long    GetInt64(int o)   => (long)GetValue(o);
    public override float   GetFloat(int o)   => (float)GetValue(o);
    public override double  GetDouble(int o)  => (double)GetValue(o);
    public override char    GetChar(int o)    => (char)GetValue(o);
    public override long GetBytes(int o, long dOff, byte[]? buf, int bOff, int len) => 0;
    public override long GetChars(int o, long dOff, char[]? buf, int bOff, int len) => 0;
    public override int  GetValues(object[] values) => 0;
    public override string GetDataTypeName(int o) => GetFieldType(o).Name;
    public override System.Collections.IEnumerator GetEnumerator() => throw new NotSupportedException();
}

public sealed class TelemetryBulkIngestor
{
    private readonly string _connectionString;
    private const int DefaultBatchSize       = 5_000;
    private const int DefaultBulkCopyTimeout = 120;

    public TelemetryBulkIngestor(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task BulkInsertAsync(
        IAsyncEnumerable<TelemetryEvent> events,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        using var bulkCopy = new SqlBulkCopy(
            connection,
            SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints,
            externalTransaction: null)
        {
            DestinationTableName = "dbo.IotTelemetryEvents",
            BatchSize            = DefaultBatchSize,
            BulkCopyTimeout      = DefaultBulkCopyTimeout,
            EnableStreaming       = true   // required when passing a DbDataReader
        };

        // Column mappings: reader GetName(ordinal) -> SQL Server column name
        bulkCopy.ColumnMappings.Add("EventId",       "EventId");
        bulkCopy.ColumnMappings.Add("TenantId",      "TenantId");
        bulkCopy.ColumnMappings.Add("DeviceCode",    "DeviceCode");
        bulkCopy.ColumnMappings.Add("SensorReading", "SensorReading");
        bulkCopy.ColumnMappings.Add("ReceivedAtUtc", "ReceivedAtUtc");

        // Pass the custom DbDataReader subclass to WriteToServerAsync — NOT a DataTable
        using var reader = new TelemetryEventReader(events, cancellationToken);
        await bulkCopy.WriteToServerAsync(reader, cancellationToken).ConfigureAwait(false);
    }
}
```

### Key Architectural Highlights:
- **`DbDataReader` subclass with `override bool Read()`**: `TelemetryEventReader` inherits from `DbDataReader` and overrides `Read()` and `GetValue(int ordinal)` — the two core methods SqlBulkCopy's internal row pump calls in its tight loop. Do NOT use DataTable or manual batch lists.
- **`WriteToServerAsync(DbDataReader, CancellationToken)`**: The correct SqlBulkCopy API for custom reader ingestion. Pass the DbDataReader instance directly — the pump will call `Read()` and `GetValue()` on it.
- **`EnableStreaming = true`**: Required on `SqlBulkCopy` when passing a `DbDataReader` to enable server-side streaming and prevent full result-set buffering.
- **Async bridge via `GetAwaiter().GetResult()`**: SqlBulkCopy calls `Read()` synchronously on a dedicated thread pool thread. Bridging `MoveNextAsync()` with `.AsTask().GetAwaiter().GetResult()` is safe here as there is no SynchronizationContext to deadlock against.

