public static class CrmLeadEndpoints
{
    public static RouteGroupBuilder MapCrmLeadEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/crm/leads")
            .WithTags("CRM Lead Qualification Transition")
            .RequireAuthorization();

        group.MapPost("/{id:guid}/process",
            async Task<Results<Ok<CrmLeadResult>, NotFound, Conflict, BadRequest<ProblemDetails>>> (
                Guid id,
                ICrmLeadService service,
                ILogger<CrmLeadEndpoints> logger,
                CancellationToken ct) =>
            {
                logger.LogInformation("Processing {EntityId} for CRM Lead Qualification Transition", id);
                try
                {
                    var result = await service.ProcessAsync(id, ct);
                    return result is null
                        ? TypedResults.NotFound()
                        : TypedResults.Ok(result);
                }
                catch (SqlException ex) when (ex.Number == 54001)
                {
                    logger.LogWarning(ex, "Conflict on CRM Lead Qualification Transition: SqlError {Number}", ex.Number);
                    return TypedResults.Conflict(new ProblemDetails
                    {
                        Title  = "State Conflict",
                        Detail = ex.Message,
                        Status = StatusCodes.Status409Conflict
                    });
                }
                catch (SqlException ex) when (ex.Number == 54002)
                {
                    logger.LogWarning(ex, "Validation failure on CRM Lead Qualification Transition: SqlError {Number}", ex.Number);
                    return TypedResults.BadRequest(new ProblemDetails
                    {
                        Title  = "Business Rule Violation",
                        Detail = ex.Message,
                        Status = StatusCodes.Status400BadRequest
                    });
                }
            })
        // AddEndpointFilter<T>() is chained directly on the route — not on the group.
        // This registers TenantContextFilter as the outermost pipeline step.
        .AddEndpointFilter<TenantContextFilter>()
        .WithName("ProcessCrmLead")
        .Produces<CrmLeadResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status404NotFound)
        .ProducesProblem(StatusCodes.Status409Conflict)
        .ProducesValidationProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}

public interface ICrmLeadService
{
    Task<CrmLeadResult?> ProcessAsync(Guid id, CancellationToken ct);
}
