using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseBMS.Infrastructure.Data;

public readonly record struct TaskUpdateDto(
    int TaskId,
    string Status,
    decimal HoursLogged,
    int PercentComplete,
    string Notes
);

public sealed class ProjectTaskManager
{
    private readonly string _connectionString;

    public ProjectTaskManager(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<(int UpdatedRows, decimal TotalHoursLogged)> BatchUpdateTasksAsync(
        Guid projectId,
        Guid modifiedByUserId,
        IReadOnlyList<TaskUpdateDto> taskUpdates,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Bms_BatchUpdateProjectTasks", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        // Standard structured parameter mapping for Table-Valued Parameter
        var tableData = CreateTaskUpdateDataTable(taskUpdates);

        var tvpParam = command.Parameters.AddWithValue("@TaskUpdates", tableData);
        tvpParam.SqlDbType = SqlDbType.Structured;
        tvpParam.TypeName = "dbo.BmsTaskUpdateType"; // Defined in SQL Server as CREATE TYPE

        command.Parameters.Add(new SqlParameter("@ProjectId", SqlDbType.UniqueIdentifier) { Value = projectId });
        command.Parameters.Add(new SqlParameter("@ModifiedByUserId", SqlDbType.UniqueIdentifier) { Value = modifiedByUserId });

        // Output parameters for real-time aggregation
        var paramRowsUpdated = new SqlParameter("@RowsUpdated", SqlDbType.Int)
        {
            Direction = ParameterDirection.Output
        };
        var paramTotalHours = new SqlParameter("@TotalHoursCalculated", SqlDbType.Decimal)
        {
            Direction = ParameterDirection.Output,
            Precision = 10,
            Scale = 2
        };

        command.Parameters.Add(paramRowsUpdated);
        command.Parameters.Add(paramTotalHours);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        int updatedCount = paramRowsUpdated.Value is int count ? count : 0;
        decimal totalHours = paramTotalHours.Value is decimal hours ? hours : 0m;

        return (updatedCount, totalHours);
    }

    private static DataTable CreateTaskUpdateDataTable(IReadOnlyList<TaskUpdateDto> items)
    {
        var dt = new DataTable();
        dt.Columns.Add("TaskId", typeof(int));
        dt.Columns.Add("Status", typeof(string));
        dt.Columns.Add("HoursLogged", typeof(decimal));
        dt.Columns.Add("PercentComplete", typeof(int));
        dt.Columns.Add("Notes", typeof(string));

        foreach (var item in items)
        {
            dt.Rows.Add(
                item.TaskId,
                item.Status,
                item.HoursLogged,
                item.PercentComplete,
                item.Notes ?? (object)DBNull.Value
            );
        }

        return dt;
    }
}
