```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseERP.Infrastructure.Data;

public sealed record StockMovementEntry(
    Guid MovementId,
    Guid TenantId,
    string Sku,
    int WarehouseId,
    int LocationBinId,
    decimal Quantity,
    string MovementType,
    string ReferenceDocumentNumber,
    DateTimeOffset TimestampUtc
);

public sealed class BulkStockMovementService
{
    private readonly string _connectionString;

    public BulkStockMovementService(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<long> BulkInsertStockMovementsAsync(
        IReadOnlyList<StockMovementEntry> entries,
        int batchSize = 5000,
        CancellationToken cancellationToken = default)
    {
        if (entries == null || entries.Count == 0) return 0;

        // Construct strongly-typed in-memory DataTable to feed SqlBulkCopy
        using var table = new DataTable("ErpStockMovements");
        table.Columns.Add("MovementId", typeof(Guid));
        table.Columns.Add("TenantId", typeof(Guid));
        table.Columns.Add("Sku", typeof(string));
        table.Columns.Add("WarehouseId", typeof(int));
        table.Columns.Add("LocationBinId", typeof(int));
        table.Columns.Add("Quantity", typeof(decimal));
        table.Columns.Add("MovementType", typeof(string));
        table.Columns.Add("ReferenceDocumentNumber", typeof(string));
        table.Columns.Add("TimestampUtc", typeof(DateTimeOffset));

        foreach (var item in entries)
        {
            table.Rows.Add(
                item.MovementId,
                item.TenantId,
                item.Sku,
                item.WarehouseId,
                item.LocationBinId,
                item.Quantity,
                item.MovementType,
                item.ReferenceDocumentNumber ?? (object)DBNull.Value,
                item.TimestampUtc
            );
        }

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Enforce transactional consistency across bulk copy
        await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(
            IsolationLevel.ReadCommitted, 
            cancellationToken
        ).ConfigureAwait(false);

        try
        {
            using var bulkCopy = new SqlBulkCopy(
                connection, 
                SqlBulkCopyOptions.CheckConstraints | 
                SqlBulkCopyOptions.FireTriggers | 
                SqlBulkCopyOptions.TableLock, 
                transaction)
            {
                DestinationTableName = "dbo.ErpStockMovements",
                BatchSize = batchSize,
                BulkCopyTimeout = 180,
                EnableStreaming = true
            };

            // Explicit column mappings prevent silent column ordering bugs
            bulkCopy.ColumnMappings.Add("MovementId", "MovementId");
            bulkCopy.ColumnMappings.Add("TenantId", "TenantId");
            bulkCopy.ColumnMappings.Add("Sku", "Sku");
            bulkCopy.ColumnMappings.Add("WarehouseId", "WarehouseId");
            bulkCopy.ColumnMappings.Add("LocationBinId", "LocationBinId");
            bulkCopy.ColumnMappings.Add("Quantity", "Quantity");
            bulkCopy.ColumnMappings.Add("MovementType", "MovementType");
            bulkCopy.ColumnMappings.Add("ReferenceDocumentNumber", "ReferenceDocumentNumber");
            bulkCopy.ColumnMappings.Add("TimestampUtc", "TimestampUtc");

            long rowsCopied = 0;
            bulkCopy.SqlRowsCopied += (sender, e) => rowsCopied = e.RowsCopied;
            bulkCopy.NotifyAfter = batchSize;

            await bulkCopy.WriteToServerAsync(table, cancellationToken).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);

            return entries.Count;
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }
}
```

