```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseDomain.Infrastructure.Data;

public sealed record CrmOpportunityDto(
    Guid OpportunityId,
    Guid TenantId,
    string StageName,
    decimal ExpectedRevenue,
    DateTimeOffset CreatedAtUtc
);

public sealed class CrmOpportunityRepository
{
    private readonly string _connectionString;

    public CrmOpportunityRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Inserts a new CrmOpportunity record and returns the generated UUID atomically.
    /// </summary>
    public async Task<Guid> CreateAsync(CrmOpportunityDto dto, CancellationToken cancellationToken = default)
    {
        const string sql = @"
            INSERT INTO dbo.CrmOpportunitys (
                TenantId, 
                StageName, 
                ExpectedRevenue, 
                CreatedAtUtc
            )
            OUTPUT inserted.OpportunityId
            VALUES (
                @TenantId, 
                @StageName, 
                @ExpectedRevenue, 
                SYSUTCDATETIME()
            );";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = dto.TenantId });
        command.Parameters.Add(new SqlParameter("@StageName", SqlDbType.NVarChar, 50) { Value = dto.StageName });

        var numParam = new SqlParameter("@ExpectedRevenue", SqlDbType.Decimal)
        {
            Precision = 18,
            Scale = 2,
            Value = dto.ExpectedRevenue
        };
        command.Parameters.Add(numParam);

        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return (Guid)result!;
    }

    /// <summary>
    /// Streams paginated CrmOpportunity records without materializing full lists in RAM.
    /// </summary>
    public async IAsyncEnumerable<CrmOpportunityDto> StreamPagedAsync(
        Guid tenantId,
        int pageNumber,
        int pageSize,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                OpportunityId, 
                TenantId, 
                StageName, 
                ExpectedRevenue, 
                CreatedAtUtc
            FROM dbo.CrmOpportunitys WITH (READPAST)
            WHERE TenantId = @TenantId
            ORDER BY CreatedAtUtc DESC
            OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection);
        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@Offset", SqlDbType.Int) { Value = (pageNumber - 1) * pageSize });
        command.Parameters.Add(new SqlParameter("@PageSize", SqlDbType.Int) { Value = pageSize });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection, 
            cancellationToken
        ).ConfigureAwait(false);

        int ordId = reader.GetOrdinal("OpportunityId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordStatus = reader.GetOrdinal("StageName");
        int ordNum = reader.GetOrdinal("ExpectedRevenue");
        int ordCreated = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new CrmOpportunityDto(
                OpportunityId: reader.GetGuid(ordId),
                TenantId: reader.GetGuid(ordTenant),
                StageName: reader.GetString(ordStatus),
                ExpectedRevenue: reader.GetDecimal(ordNum),
                CreatedAtUtc: reader.GetDateTimeOffset(ordCreated)
            );
        }
    }

    /// <summary>
    /// Updates status atomically under Snapshot Isolation to prevent read blocking.
    /// </summary>
    public async Task<bool> UpdateStatusAsync(
        Guid OpportunityId, 
        string newStatus, 
        CancellationToken cancellationToken = default)
    {
        const string sql = @"
            UPDATE dbo.CrmOpportunitys
            SET StageName = @NewStatus
            WHERE OpportunityId = @OpportunityId;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(
            IsolationLevel.Snapshot, 
            cancellationToken
        ).ConfigureAwait(false);

        try
        {
            await using var command = new SqlCommand(sql, connection, transaction);
            command.Parameters.Add(new SqlParameter("@OpportunityId", SqlDbType.UniqueIdentifier) { Value = OpportunityId });
            command.Parameters.Add(new SqlParameter("@NewStatus", SqlDbType.NVarChar, 50) { Value = newStatus });

            int affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return affected > 0;
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }
}
```

### Key Architectural Highlights:
- Identity Retrieval: Retrieves the generated UUID atomically upon insertion via OUTPUT inserted.OpportunityId.
- Memory-Efficient Streaming: Streams paginated `CrmOpportunityDto` records asynchronously using IAsyncEnumerable with SequentialAccess.
- Snapshot Isolation: Executes atomic status updates under Snapshot isolation to prevent read blocking.

