- Minimal API Typed Results: Employs typed Result unions and claims extraction.

Here is the complete enterprise high-throughput IoT telematics ingestion architecture:

### 1. SQL Server T-SQL Database Tier (`Databases/IoTDb/Scripts/TelematicsSchema.sql`)
```sql
CREATE TABLE dbo.DeviceTelemetry
(
    TelemetryId    BIGINT           IDENTITY(1,1) NOT NULL,
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    DeviceId       NVARCHAR(50)     NOT NULL,
    TimestampUtc   DATETIME2(3)     NOT NULL,
    MetricName     VARCHAR(50)      NOT NULL,
    MetricValue    FLOAT            NOT NULL,
    SignalQuality  TINYINT          NOT NULL CONSTRAINT DF_DeviceTelemetry_Quality DEFAULT 100,
    IngestedAtUtc  DATETIME2(3)     NOT NULL CONSTRAINT DF_DeviceTelemetry_Ingested DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_DeviceTelemetry PRIMARY KEY CLUSTERED (TenantId, DeviceId, TimestampUtc, MetricName)
)
WITH (DATA_COMPRESSION = PAGE);
GO

CREATE NONCLUSTERED INDEX IX_DeviceTelemetry_DeviceTime
ON dbo.DeviceTelemetry (TenantId, DeviceId, TimestampUtc)
INCLUDE (MetricName, MetricValue)
WITH (DATA_COMPRESSION = PAGE);
GO

-- Staging Table for Bulk Ingestion
CREATE TABLE dbo.DeviceTelemetry_Staging
(
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    DeviceId       NVARCHAR(50)     NOT NULL,
    TimestampUtc   DATETIME2(3)     NOT NULL,
    MetricName     VARCHAR(50)      NOT NULL,
    MetricValue    FLOAT            NOT NULL,
    SignalQuality  TINYINT          NOT NULL
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_IoT_MergeStagingTelemetry
    @TenantId      UNIQUEIDENTIFIER,
    @MergedCount   INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Set-based idempotent merge from staging into permanent partitioned telemetry table
        INSERT INTO dbo.DeviceTelemetry (TenantId, DeviceId, TimestampUtc, MetricName, MetricValue, SignalQuality)
        SELECT 
            s.TenantId,
            s.DeviceId,
            s.TimestampUtc,
            s.MetricName,
            s.MetricValue,
            s.SignalQuality
        FROM dbo.DeviceTelemetry_Staging s
        WHERE s.TenantId = @TenantId
          AND NOT EXISTS (
              SELECT 1 
              FROM dbo.DeviceTelemetry t WITH (UPDLOCK, HOLDLOCK)
              WHERE t.TenantId = s.TenantId
                AND t.DeviceId = s.DeviceId
                AND t.TimestampUtc = s.TimestampUtc
                AND t.MetricName = s.MetricName
          );

        SET @MergedCount = @@ROWCOUNT;

        -- Clear staging buffer for current tenant
        DELETE FROM dbo.DeviceTelemetry_Staging
        WHERE TenantId = @TenantId;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

### 2. C# .NET 10 ADO.NET Data Access Tier (`src/Infrastructure/Data/BulkTelemetryIngestionRepository.cs`)
```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace EnterpriseIoT.Infrastructure.Data;

public sealed record TelemetryPointDto(
    Guid TenantId,
    string DeviceId,
    DateTime TimestampUtc,
    string MetricName,
    double MetricValue,
    byte SignalQuality
);

public sealed class BulkTelemetryIngestionRepository
{
    private readonly string _connectionString;

    public BulkTelemetryIngestionRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<int> IngestTelemetryBatchAsync(
        Guid tenantId,
        IEnumerable<TelemetryPointDto> telemetryStream,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(telemetryStream);

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // 1. Zero-Allocation Streaming Bulk Copy into Staging Table
        using (var bulkCopy = new SqlBulkCopy(connection, SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
        {
            bulkCopy.DestinationTableName = "dbo.DeviceTelemetry_Staging";
            bulkCopy.BatchSize = 10_000;
            bulkCopy.BulkCopyTimeout = 60;

            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.TenantId), "TenantId");
            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.DeviceId), "DeviceId");
            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.TimestampUtc), "TimestampUtc");
            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.MetricName), "MetricName");
            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.MetricValue), "MetricValue");
            bulkCopy.ColumnMappings.Add(nameof(TelemetryPointDto.SignalQuality), "SignalQuality");

            using var reader = new TelemetryDataReader(telemetryStream);
            await bulkCopy.WriteToServerAsync(reader, cancellationToken).ConfigureAwait(false);
        }

        // 2. Execute Atomic Idempotent Staging Merge Procedure
        await using var mergeCmd = new SqlCommand("dbo.usp_IoT_MergeStagingTelemetry", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 60
        };

        mergeCmd.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });

        var mergedCountParam = new SqlParameter("@MergedCount", SqlDbType.Int)
        {
            Direction = ParameterDirection.Output
        };
        mergeCmd.Parameters.Add(mergedCountParam);

        await mergeCmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        return mergedCountParam.Value is int count ? count : 0;
    }

    // High-Performance Streaming IDataReader Wrapper for Zero-Allocation SqlBulkCopy
    private sealed class TelemetryDataReader : DbDataReader
    {
        private readonly IEnumerator<TelemetryPointDto> _enumerator;
        private bool _isClosed;

        public TelemetryDataReader(IEnumerable<TelemetryPointDto> source)
        {
            _enumerator = source.GetEnumerator();
        }

        public override bool Read() => _enumerator.MoveNext();

        public override int FieldCount => 6;

        public override object GetValue(int ordinal) => ordinal switch
        {
            0 => _enumerator.Current.TenantId,
            1 => _enumerator.Current.DeviceId,
            2 => _enumerator.Current.TimestampUtc,
            3 => _enumerator.Current.MetricName,
            4 => _enumerator.Current.MetricValue,
            5 => _enumerator.Current.SignalQuality,
            _ => throw new IndexOutOfRangeException()
        };

        public override string GetName(int ordinal) => ordinal switch
        {
            0 => "TenantId",
            1 => "DeviceId",
            2 => "TimestampUtc",
            3 => "MetricName",
            4 => "MetricValue",
            5 => "SignalQuality",
            _ => throw new IndexOutOfRangeException()
        };

        public override int GetOrdinal(string name) => name switch
        {
            "TenantId" => 0,
            "DeviceId" => 1,
            "TimestampUtc" => 2,
            "MetricName" => 3,
            "MetricValue" => 4,
            "SignalQuality" => 5,
            _ => -1
        };

        public override bool IsDBNull(int ordinal) => false;
        public override bool HasRows => true;
        public override bool IsClosed => _isClosed;
        public override int RecordsAffected => -1;
        public override int Depth => 0;

        public override void Close()
        {
            _isClosed = true;
            _enumerator.Dispose();
        }

        public override Type GetFieldType(int ordinal) => typeof(object);
        public override string GetDataTypeName(int ordinal) => "variant";
        public override int GetValues(object[] values) => 0;
        public override bool NextResult() => false;

        public override bool GetBoolean(int ordinal) => (bool)GetValue(ordinal);
        public override byte GetByte(int ordinal) => (byte)GetValue(ordinal);
        public override long GetBytes(int ordinal, long dataOffset, byte[]? buffer, int bufferOffset, int length) => 0;
        public override char GetChar(int ordinal) => (char)GetValue(ordinal);
        public override long GetChars(int ordinal, long dataOffset, char[]? buffer, int bufferOffset, int length) => 0;
        public override Guid GetGuid(int ordinal) => (Guid)GetValue(ordinal);
        public override short GetInt16(int ordinal) => (short)GetValue(ordinal);
        public override int GetInt32(int ordinal) => (int)GetValue(ordinal);
        public override long GetInt64(int ordinal) => (long)GetValue(ordinal);
        public override float GetFloat(int ordinal) => (float)GetValue(ordinal);
        public override double GetDouble(int ordinal) => (double)GetValue(ordinal);
        public override string GetString(int ordinal) => (string)GetValue(ordinal);
        public override decimal GetDecimal(int ordinal) => (decimal)GetValue(ordinal);
        public override DateTime GetDateTime(int ordinal) => (DateTime)GetValue(ordinal);
        public override System.Collections.IEnumerator GetEnumerator() => _enumerator;
    }
}
