using EnterpriseIoT.Infrastructure.Data;

namespace EnterpriseIoT.Api;

public static class TelemetryEndpoints
{
    public static RouteGroupBuilder MapTelemetryEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/v1/iot/telemetry")
            .WithTags("IoT Telemetry Ingestion")
            .RequireAuthorization();

        group.MapPost("/batch", async Task<Results<Ok<TelemetryBatchIngestionResult>, BadRequest<ProblemDetails>>> (
            IngestTelemetryBatchRequest request,
            BulkTelemetryIngestionRepository repository,
            CancellationToken cancellationToken) =>
        {
            if (request.Points is null || request.Points.Count == 0)
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
                    Title = "Empty Batch",
                    Detail = "Telemetry payload must contain at least one metric point."
                });
            }

            int count = await repository.IngestTelemetryBatchAsync(
                tenantId: request.TenantId,
                telemetryStream: request.Points,
                cancellationToken: cancellationToken
            );

            return TypedResults.Ok(new TelemetryBatchIngestionResult(
                TotalIngested: count,
                IngestedAtUtc: DateTimeOffset.UtcNow
            ));
        })
        .WithName("IngestTelemetryBatch")
        .Produces<TelemetryBatchIngestionResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest);

        return group;
    }
}

public sealed record IngestTelemetryBatchRequest(
    Guid TenantId,
    IReadOnlyList<TelemetryPointDto> Points
);

public sealed record TelemetryBatchIngestionResult(
    int TotalIngested,
    DateTimeOffset IngestedAtUtc
);
