namespace Enterprise.FuelDepot.Infrastructure.Data;

public sealed class FifoRepository
{
    private readonly string _connectionString;

    public FifoRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<(decimal Allocated, decimal Remaining)> AllocateStockAsync(
        Guid tenantId,
        Guid warehouseId,
        string fuelgrade,
        decimal requiredQty,
        CancellationToken cancellationToken = default)
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Fuel_PumpInventoryFifo", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@WarehouseId", SqlDbType.UniqueIdentifier) { Value = warehouseId });
        command.Parameters.Add(new SqlParameter("@FuelGrade", SqlDbType.NVarChar, 50) { Value = fuelgrade });
        command.Parameters.Add(new SqlParameter("@RequiredQty", SqlDbType.Decimal) { Precision = 18, Scale = 2, Value = requiredQty });

        var outAlloc = new SqlParameter("@AllocatedQty", SqlDbType.Decimal) { Precision = 18, Scale = 2, Direction = ParameterDirection.Output };
        var outRem = new SqlParameter("@RemainingQty", SqlDbType.Decimal) { Precision = 18, Scale = 2, Direction = ParameterDirection.Output };
        command.Parameters.Add(outAlloc);
        command.Parameters.Add(outRem);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        var allocated = outAlloc.Value is decimal a ? a : 0.00m;
        var remaining = outRem.Value is decimal r ? r : 0.00m;

        return (allocated, remaining);
    }
}
