using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace Enterprise.HR.Infrastructure.Data;

public readonly record struct PayrollSlipSummaryDto(
    Guid SlipId,
    Guid TenantId,
    string EmployeeNumber,
    decimal NetPay,
    DateTimeOffset CreatedAtUtc
);

public sealed class PayrollSlipRepository
{
    private readonly string _connectionString;

    public PayrollSlipRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    /// <summary>
    /// Streams PayrollSlip records asynchronously with SequentialAccess and zero intermediate buffering.
    /// </summary>
    public async IAsyncEnumerable<PayrollSlipSummaryDto> StreamActiveRecordsAsync(
        Guid tenantId,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        const string sql = @"
            SELECT 
                SlipId,
                TenantId,
                EmployeeNumber,
                NetPay,
                CreatedAtUtc
            FROM dbo.PayrollSlips WITH (READPAST)
            WHERE TenantId = @TenantId
              AND IsActive = 1
            ORDER BY CreatedAtUtc DESC;";

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand(sql, connection)
        {
            CommandType = CommandType.Text,
            CommandTimeout = 30
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });

        await using var reader = await command.ExecuteReaderAsync(
            CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection,
            cancellationToken
        ).ConfigureAwait(false);

        int ordId = reader.GetOrdinal("SlipId");
        int ordTenant = reader.GetOrdinal("TenantId");
        int ordCode = reader.GetOrdinal("EmployeeNumber");
        int ordVal = reader.GetOrdinal("NetPay");
        int ordDate = reader.GetOrdinal("CreatedAtUtc");

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            var id = await reader.GetFieldValueAsync<Guid>(ordId, cancellationToken).ConfigureAwait(false);
            var tenant = await reader.GetFieldValueAsync<Guid>(ordTenant, cancellationToken).ConfigureAwait(false);
            var code = await reader.GetFieldValueAsync<string>(ordCode, cancellationToken).ConfigureAwait(false);
            var value = await reader.GetFieldValueAsync<decimal>(ordVal, cancellationToken).ConfigureAwait(false);
            var date = await reader.GetFieldValueAsync<DateTimeOffset>(ordDate, cancellationToken).ConfigureAwait(false);

            yield return new PayrollSlipSummaryDto(id, tenant, code, value, date);
        }
    }
}
