-- ============================================================================
-- Description: Convert CRM Lead into Account, Contact, and Opportunity atomically
-- Engine: SQL Server 2022+ / Azure SQL Database
-- ============================================================================

CREATE OR ALTER PROCEDURE dbo.usp_Crm_ConvertLeadToOpportunity
    @TenantId              UNIQUEIDENTIFIER,
    @LeadId                UNIQUEIDENTIFIER,
    @ConvertedByUserId     UNIQUEIDENTIFIER,
    @OpportunityName       NVARCHAR(200),
    @EstimatedAmount       DECIMAL(18, 2),
    @CloseDate             DATE,
    @ExistingAccountId     UNIQUEIDENTIFIER = NULL,
    @NewAccountIdOut       UNIQUEIDENTIFIER OUTPUT,
    @NewContactIdOut       UNIQUEIDENTIFIER OUTPUT,
    @NewOpportunityIdOut   UNIQUEIDENTIFIER OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Pre-validation
    DECLARE @LeadStatus NVARCHAR(50);
    DECLARE @CompanyName NVARCHAR(200);
    DECLARE @FirstName NVARCHAR(100);
    DECLARE @LastName NVARCHAR(100);
    DECLARE @Email NVARCHAR(255);
    DECLARE @Phone NVARCHAR(50);

    SELECT 
        @LeadStatus = Status,
        @CompanyName = CompanyName,
        @FirstName = FirstName,
        @LastName = LastName,
        @Email = Email,
        @Phone = Phone
    FROM dbo.CrmLeads WITH (UPDLOCK, ROWLOCK)
    WHERE TenantId = @TenantId AND LeadId = @LeadId;

    IF @LeadStatus IS NULL
    BEGIN
        THROW 52001, 'Lead record does not exist for the specified Tenant.', 1;
        RETURN;
    END

    IF @LeadStatus = 'Converted'
    BEGIN
        THROW 52002, 'Lead has already been converted.', 1;
        RETURN;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Resolve or Create Account
        IF @ExistingAccountId IS NOT NULL
        BEGIN
            SET @NewAccountIdOut = @ExistingAccountId;
        END
        ELSE
        BEGIN
            SET @NewAccountIdOut = NEWID();
            INSERT INTO dbo.CrmAccounts (AccountId, TenantId, AccountName, Phone, CreatedByUserId, CreatedAtUtc, IsActive)
            VALUES (@NewAccountIdOut, @TenantId, ISNULL(@CompanyName, @LastName + ' (Individual)'), @Phone, @ConvertedByUserId, SYSUTCDATETIME(), 1);
        END

        -- 2. Create Primary Contact
        SET @NewContactIdOut = NEWID();
        INSERT INTO dbo.CrmContacts (ContactId, TenantId, AccountId, FirstName, LastName, Email, Phone, CreatedByUserId, CreatedAtUtc, IsActive)
        VALUES (@NewContactIdOut, @TenantId, @NewAccountIdOut, @FirstName, @LastName, @Email, @Phone, @ConvertedByUserId, SYSUTCDATETIME(), 1);

        -- 3. Create Sales Opportunity
        SET @NewOpportunityIdOut = NEWID();
        INSERT INTO dbo.CrmOpportunities (OpportunityId, TenantId, AccountId, PrimaryContactId, OpportunityName, Stage, EstimatedAmount, TargetCloseDate, CreatedByUserId, CreatedAtUtc, IsActive)
        VALUES (@NewOpportunityIdOut, @TenantId, @NewAccountIdOut, @NewContactIdOut, @OpportunityName, 'Qualification', @EstimatedAmount, @CloseDate, @ConvertedByUserId, SYSUTCDATETIME(), 1);

        -- 4. Mark Lead as Converted
        UPDATE dbo.CrmLeads
        SET Status = 'Converted',
            ConvertedOpportunityId = @NewOpportunityIdOut,
            ConvertedAtUtc = SYSUTCDATETIME(),
            ConvertedByUserId = @ConvertedByUserId
        WHERE TenantId = @TenantId AND LeadId = @LeadId;

        -- 5. Audit Trail Entry
        INSERT INTO dbo.AuditLedger (TenantId, EntityType, EntityId, Action, PerformedByUserId, TimestampUtc, DetailsJson)
        VALUES (@TenantId, 'CrmLead', @LeadId, 'CONVERTED', @ConvertedByUserId, SYSUTCDATETIME(), 
            (SELECT @NewAccountIdOut AS AccountId, @NewContactIdOut AS ContactId, @NewOpportunityIdOut AS OpportunityId FOR JSON PATH, WITHOUT_ARRAY_WRAPPER));

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
