    RowVer           ROWVERSION       NOT NULL,
    CONSTRAINT PK_InventoryLots PRIMARY KEY CLUSTERED (LotId),
    CONSTRAINT FK_InventoryLots_Warehouse FOREIGN KEY (WarehouseId) REFERENCES dbo.Warehouses (WarehouseId)
