GO

CREATE NONCLUSTERED INDEX IX_InventoryLots_FifoAllocation
ON dbo.InventoryLots (TenantId, WarehouseId, Sku, ReceivedAtUtc)
INCLUDE (RemainingQuantity, UnitCost)
WHERE RemainingQuantity > 0;
GO

CREATE TABLE dbo.InventoryAllocations
(
    AllocationId   UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_InventoryAllocations_Id DEFAULT NEWSEQUENTIALID(),
    TenantId       UNIQUEIDENTIFIER NOT NULL,
    OrderId        UNIQUEIDENTIFIER NOT NULL,
    LotId          UNIQUEIDENTIFIER NOT NULL,
    AllocatedQty   INT              NOT NULL CHECK (AllocatedQty > 0),
    UnitCost       DECIMAL(18, 4)   NOT NULL,
    AllocatedAtUtc DATETIME2(7)     NOT NULL CONSTRAINT DF_InventoryAllocations_Date DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_InventoryAllocations PRIMARY KEY CLUSTERED (AllocationId),
    CONSTRAINT FK_InventoryAllocations_Lot FOREIGN KEY (LotId) REFERENCES dbo.InventoryLots (LotId)
);
GO

CREATE TYPE dbo.tvp_SkuDepletionRequest AS TABLE
(
    Sku          NVARCHAR(50) NOT NULL,
    RequestedQty INT          NOT NULL CHECK (RequestedQty > 0)
);
GO

CREATE OR ALTER PROCEDURE dbo.usp_Inventory_DepleteFifoStock
    @TenantId      UNIQUEIDENTIFIER,
    @WarehouseId   UNIQUEIDENTIFIER,
    @OrderId       UNIQUEIDENTIFIER,
    @DepletionList dbo.tvp_SkuDepletionRequest READONLY,
    @AllocatedCount INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Temporary storage for allocated lots
        DECLARE @AllocationResults TABLE
        (
            LotId        UNIQUEIDENTIFIER NOT NULL,
            AllocatedQty INT              NOT NULL,
            UnitCost     DECIMAL(18, 4)   NOT NULL
        );

        -- Set-based FIFO Running Total Calculation & Depletion
        WITH AvailableLots AS
        (
            SELECT 
                l.LotId,
                l.Sku,
                l.RemainingQuantity,
                l.UnitCost,
                req.RequestedQty,
                SUM(l.RemainingQuantity) OVER (
                    PARTITION BY l.Sku 
                    ORDER BY l.ReceivedAtUtc, l.LotId 
                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
                ) AS RunningTotal,
                SUM(l.RemainingQuantity) OVER (
                    PARTITION BY l.Sku
                ) AS TotalAvailableForSku
            FROM dbo.InventoryLots l WITH (UPDLOCK, ROWLOCK)
            INNER JOIN @DepletionList req ON l.Sku = req.Sku
            WHERE l.TenantId = @TenantId
              AND l.WarehouseId = @WarehouseId
              AND l.RemainingQuantity > 0
        ),
        DepletionCalculation AS
        (
            SELECT 
                LotId,
                Sku,
                RemainingQuantity,
                UnitCost,
                RequestedQty,
                TotalAvailableForSku,
                RunningTotal,
                CASE 
                    WHEN RunningTotal <= RequestedQty THEN RemainingQuantity
                    ELSE RemainingQuantity - (RunningTotal - RequestedQty)
                END AS QtyToTake
            FROM AvailableLots
            WHERE RunningTotal - RemainingQuantity < RequestedQty
        )
        -- Verify sufficient inventory exists for every requested SKU
        SELECT @AllocatedCount = COUNT(DISTINCT Sku)
        FROM DepletionCalculation
        WHERE TotalAvailableForSku < RequestedQty;

        IF @AllocatedCount > 0
        BEGIN
            THROW 54001, 'Insufficient inventory available to satisfy FIFO depletion order.', 1;
            RETURN -1;
        END

        -- Perform Atomic Inventory Deductions
        UPDATE target
        SET target.RemainingQuantity = target.RemainingQuantity - calc.QtyToTake
        OUTPUT 
            inserted.LotId, 
            calc.QtyToTake, 
            calc.UnitCost 
        INTO @AllocationResults (LotId, AllocatedQty, UnitCost)
        FROM dbo.InventoryLots target
        INNER JOIN DepletionCalculation calc ON target.LotId = calc.LotId;

        -- Record Allocation Ledger Entries
        INSERT INTO dbo.InventoryAllocations (TenantId, OrderId, LotId, AllocatedQty, UnitCost)
        SELECT @TenantId, @OrderId, LotId, AllocatedQty, UnitCost
        FROM @AllocationResults;

        SELECT @AllocatedCount = COUNT(*) FROM @AllocationResults;

        COMMIT TRANSACTION;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
```

