namespace EnterpriseWms.Infrastructure.Data;

public sealed record SkuDepletionItem(string Sku, int RequestedQuantity);
public sealed record FifoDepletionResult(Guid OrderId, int TotalLotsAllocated, DateTimeOffset AllocatedAtUtc);

public sealed class WarehouseInventoryRepository
{
    private readonly string _connectionString;

    public WarehouseInventoryRepository(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public async Task<FifoDepletionResult> DepleteInventoryFifoAsync(
        Guid tenantId,
        Guid warehouseId,
        Guid orderId,
        IReadOnlyList<SkuDepletionItem> items,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(items);
        if (items.Count == 0)
        {
            throw new ArgumentException("Depletion request list cannot be empty.", nameof(items));
        }

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqlCommand("dbo.usp_Inventory_DepleteFifoStock", connection)
        {
            CommandType = CommandType.StoredProcedure,
            CommandTimeout = 45
        };

        command.Parameters.Add(new SqlParameter("@TenantId", SqlDbType.UniqueIdentifier) { Value = tenantId });
        command.Parameters.Add(new SqlParameter("@WarehouseId", SqlDbType.UniqueIdentifier) { Value = warehouseId });
        command.Parameters.Add(new SqlParameter("@OrderId", SqlDbType.UniqueIdentifier) { Value = orderId });

        var tvpParam = new SqlParameter("@DepletionList", SqlDbType.Structured)
        {
            TypeName = "dbo.tvp_SkuDepletionRequest",
            Value = BuildDepletionDataTable(items)
        };
        command.Parameters.Add(tvpParam);

        var allocatedCountParam = new SqlParameter("@AllocatedCount", SqlDbType.Int)
        {
            Direction = ParameterDirection.Output
        };
        command.Parameters.Add(allocatedCountParam);

        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);

        int allocatedCount = allocatedCountParam.Value is int count ? count : 0;

        return new FifoDepletionResult(
            OrderId: orderId,
            TotalLotsAllocated: allocatedCount,
            AllocatedAtUtc: DateTimeOffset.UtcNow
        );
    }

    private static DataTable BuildDepletionDataTable(IReadOnlyList<SkuDepletionItem> items)
    {
        var dt = new DataTable();
        dt.Columns.Add("Sku", typeof(string));
        dt.Columns.Add("RequestedQty", typeof(int));

        foreach (var item in items)
        {
            dt.Rows.Add(item.Sku, item.RequestedQuantity);
        }

        return dt;
    }
}
