            .RequireAuthorization();

        group.MapPost("/warehouses/{warehouseId:guid}/orders/{orderId:guid}/deplete-fifo", async Task<Results<Ok<FifoDepletionResult>, BadRequest<ProblemDetails>, Conflict<ProblemDetails>>> (
            Guid warehouseId,
            Guid orderId,
            DepleteInventoryRequest request,
            WarehouseInventoryRepository repository,
            CancellationToken cancellationToken) =>
        {
            try
            {
                var result = await repository.DepleteInventoryFifoAsync(
                    tenantId: request.TenantId,
                    warehouseId: warehouseId,
                    orderId: orderId,
                    items: request.Items,
                    cancellationToken: cancellationToken
                );

                return TypedResults.Ok(result);
            }
            catch (SqlException ex) when (ex.Number == 54001)
            {
                return TypedResults.BadRequest(new ProblemDetails
                {
