                    Detail = "The inventory allocation experienced concurrent lock contention. Please retry."
                });
            }
        })
        .WithName("DepleteFifoInventory")
        .Produces<FifoDepletionResult>(StatusCodes.Status200OK)
        .ProducesProblem(StatusCodes.Status400BadRequest)
        .ProducesProblem(StatusCodes.Status409Conflict);

